const A={user:null,route:'home',site:{},terms:{scroll:'',popups:[]},profile:null,duePopup:null,dueSignature:'',popupSeen:false,noticeSeen:false,products:[],cart:[],q:'',cat:'',pay:'记账',lastRevision:0,poll:null,evt:null,perms:[],csrf:''};
const money=c=>{const n=Number(c||0),a=Math.abs(n),s=n<0?'-¥':'¥';return s+Math.floor(a/100).toLocaleString('zh-CN')+'.'+String(a%100).padStart(2,'0')};
const esc=s=>{const m={"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"};return String(s??"").replace(/[&<>"']/g,c=>m[c])};
const yuan=c=>(Number(c||0)/100).toFixed(2);
const dt=()=>{const d=new Date(Date.now()+8*3600*1000),p=n=>String(n).padStart(2,'0');return d.getUTCFullYear()+'-'+p(d.getUTCMonth()+1)+'-'+p(d.getUTCDate())+'T'+p(d.getUTCHours())+':'+p(d.getUTCMinutes())};
const today=()=>dt().slice(0,10);
const fmt=t=>String(t||'').replace('T',' ');
