function jparse(v){if(Array.isArray(v))return v;try{const x=JSON.parse(String(v||'[]'));return Array.isArray(x)?x:[]}catch{return[]}}
function parseCsvText(text){text=String(text||'').replace(/^\ufeff/,'');const lines=text.split(/\r?\n/).filter(x=>String(x).trim());return lines.map(line=>{const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(ch===','&&!q){out.push(cur);cur=''}else cur+=ch}out.push(cur);return out})}
function toast(msg,type=''){const d=document.createElement('div');d.className='toast '+type;d.textContent=msg;document.body.appendChild(d);setTimeout(()=>d.remove(),2800)}
async function api(p,o={}){const fd=typeof FormData!=='undefined'&&o.body instanceof FormData,m=String(o.method||'GET').toUpperCase(),unsafe=['POST','PUT','DELETE','PATCH'].includes(m),base=fd?{...(o.headers||{})}:{'Content-Type':'application/json',...(o.headers||{})},h={...base,...(unsafe&&A.csrf?{'x-qdt-csrf':A.csrf}:{})};const r=await fetch(p,{credentials:'same-origin',...o,headers:h});const t=await r.text();let j;try{j=JSON.parse(t)}catch{j=t}if(!r.ok||j&&(j.ok===false||j.error)){const e=new Error(j?.reason||j?.error||('HTTP '+r.status));e.payload=j||{};e.status=r.status;for(const k of ['locked','title','reason'])if(j&&j[k]!==undefined)e[k]=j[k];throw e}return j}
async function loadMe(){const j=await api('/api/auth/me');A.user=j.user;A.site=j.site||{};A.terms=j.terms||{scroll:'',popups:[]};A.profile=j.profile||null;A.duePopup=j.due_popup||null;A.overdueDays=j.overdue_days;A.perms=j.permissions||[];A.csrf=j.csrf||'';A.lastRevision=j.revision||A.lastRevision;APP.name=String(A.site.site_name||APP.name);APP.subtitle=String(A.site.site_subtitle||APP.subtitle);document.title=APP.name+' · '+APP.subtitle;renderShell()}
