function printLabel(v){if(!v)return '—';if(v==='已打印')return A.site.print_done_label||'已出单';if(v==='待打印')return A.site.print_pending_label||'待出单';if(v==='无需打印')return A.site.print_none_label||'无需出单';if(v==='失败')return A.site.print_fail_label||'出单异常';return v}
function statusLabel(v){if(v==='待确认'||v==='已确认'||v==='成功')return A.site.order_success_label||'成功';return v||'—'}
function statusBadge(v){const s=statusLabel(v),cls=s==='成功'?'ok':s==='已取消'?'err':'';return '<span class="badge '+cls+'">'+esc(s)+'</span>'}
function printBadge(v){const s=printLabel(v),cls=s.indexOf('已')>=0?'ok':s.indexOf('待')>=0?'warn':'';return '<span class="badge '+cls+'">'+esc(s)+'</span>'}
function modal(title,html,onOk,cls=''){const mask=document.createElement('div');mask.className='modal-mask '+cls;mask.innerHTML='<div class="modal"><h2>'+esc(title)+'</h2>'+html+'<div class="toolbar" style="margin-top:16px;justify-content:flex-end"><button class="btn ghost" data-close>关闭</button>'+(onOk?'<button class="btn" data-ok>确认</button>':'')+'</div></div>';document.body.appendChild(mask);const close=()=>mask.remove();mask.querySelector('[data-close]').onclick=close;mask.onclick=e=>{if(e.target===mask)close()};if(onOk)mask.querySelector('[data-ok]').onclick=async()=>{try{await onOk();close()}catch(e){toast(e.message,'err')}};setTimeout(()=>{drawAllTables();if(window.__modalBind)try{window.__modalBind()}catch(e){console.error(e)}},0);return mask}
function printHtml(title,body,opts={}){const w=window.open('','_blank','width=900,height=700');if(!w)return toast('请允许弹出打印窗口','err');const pw=Number(opts.width_mm||A.site.print_paper_width_mm||240),ph=Number(opts.height_mm||A.site.print_paper_height_mm||95.24);w.document.write('<!doctype html><html><head><meta charset="utf-8"><title></title><style>@page{size:'+pw+'mm '+ph+'mm;margin:0!important}@page{@top-left{content:""!important}@top-center{content:""!important}@top-right{content:""!important}@bottom-left{content:""!important}@bottom-center{content:""!important}@bottom-right{content:""!important}}*{box-sizing:border-box}html,body{width:'+pw+'mm;height:'+ph+'mm;margin:0;padding:0;overflow:hidden}body{font:12px/1.35 "Microsoft YaHei","SimSun",sans-serif;color:#111;background:#fff}h1,h2,h3{margin:0}table{width:100%;border-collapse:collapse}th,td{border:1px solid #333;padding:3px 4px;font-size:11px;height:22px}th{font-weight:700;text-align:center}.muted{color:#666}.right{text-align:right}.big{font-size:16px;font-weight:800}.no-border th,.no-border td{border:0}.print-form{width:'+pw+'mm;height:'+ph+'mm;padding:5mm 6mm;position:relative}.print-title{text-align:center;font-size:18px;font-weight:800;letter-spacing:2px;margin:0 0 2mm}.print-head{display:grid;grid-template-columns:1fr 1fr;gap:1mm 4mm;font-size:11px;margin-bottom:2mm}.print-head div{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.print-tbl td,.print-tbl th{height:7mm;padding:1px 4px;font-size:11px}.print-tbl .idx{width:12mm;text-align:center}.print-tbl .name{width:auto}.print-tbl .unit{width:12mm;text-align:center}.print-tbl .qty{width:14mm;text-align:center}.print-tbl .price{width:20mm;text-align:right}.print-tbl .amount{width:22mm;text-align:right}.print-tbl .note{width:26mm}.print-foot{display:grid;grid-template-columns:1fr 1fr 1fr;gap:4mm;font-size:11px;margin-top:2mm}.print-company{position:absolute;left:6mm;right:6mm;bottom:1mm;text-align:center;font-size:9px;color:#444;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}button{position:fixed;right:8px;top:8px;z-index:99}@media print{button{display:none!important}}</style></head><body>'+body+'<button id="qdt_print_btn">打印</button></body></html>');w.document.close();const btn=w.document.getElementById('qdt_print_btn');if(btn)btn.onclick=()=>w.print();setTimeout(()=>{try{w.focus()}catch{}},100)}
function deliveryNoteHtml(d){const L=d.labels||{},c=d.company||{},items=Array.isArray(d.items)?d.items:[],rows=[];const isReturn=String(d.doc_type||'')==='return';const title=isReturn?(d.return_title||String(L.title||'送货单').replace(/送货单/g,'退货单')):(L.title||'送货单');const color=isReturn?'#dc2626':'#1d4ed8';for(let i=0;i<Math.max(8,items.length);i++){const x=items[i]||{};rows.push('<tr><td class="idx">'+esc(x.index||(x.name?i+1:''))+'</td><td class="name">'+esc(x.name||'')+'</td><td class="unit">'+esc(x.unit||'')+'</td><td class="qty">'+esc(x.qty||'')+'</td><td class="price">'+esc(x.unit_price||'')+'</td><td class="amount">'+esc(x.amount||'')+'</td><td class="note">'+esc(x.note||'')+'</td></tr>')}let head='<div class="print-title" style="color:'+color+'">'+esc(title)+'</div><div class="print-head"><div>'+(L.buyer||'购买单位')+'：'+esc(d.buyer||'')+'</div><div>'+(L.saleDate||'销售日期')+'：'+esc(d.sale_date||'')+'　'+(L.billNo||'单据编号')+'：'+esc(d.bill_no||'')+'</div><div>'+(L.customerAddress||'客户地址')+'：'+esc(d.customer_address||'')+'</div><div>'+(L.customerPhone||'客户电话')+'：'+esc(d.customer_phone||'')+'</div><div></div><div>'+(L.operator||'销售开票')+'：'+esc(d.operator||'')+'</div></div>';const cols=L.columns||['商品序号','商品全名','单位','数量','单价','金额','备注'];const table='<table class="print-tbl"><thead><tr>'+cols.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'<tr><td class="idx">'+(L.total||'总计')+'</td><td>'+esc((d.sale_time||'')+' '+(d.sale_date||''))+'</td><td class="unit"></td><td class="qty">'+esc(d.total_qty||0)+'</td><td class="price"></td><td class="amount">'+esc(d.total_amount||'')+'</td><td class="note"></td></tr></tbody></table>';const foot='<div class="print-foot"><div>'+(L.bank||'收款账户')+'：'+esc(d.bank_account||'')+'</div><div>'+(L.paid||'收款金额')+'：'+esc(d.paid_amount||'')+'</div><div>'+(L.signature||'收款人签名')+'：</div></div><div class="print-company">'+esc([c.address,c.phone,c.footer].filter(Boolean).join('　'))+'</div>';return '<div class="print-form">'+head+table+foot+'</div>'}
async function printOrder(id,scope){const path=scope==='admin'?'/api/admin/orders/'+id:'/api/orders/'+id;const j=await api(path),o=j.order;let note=null;try{if(scope==='admin'){const live=await api('/api/admin/orders/'+id+'/print-payload').catch(()=>null);note=live&&live.payload||null}else{const jobs=await api('/api/company-profile').catch(()=>null);const row=(jobs&&jobs.rows||[]).find(x=>String(x.order_id||'')===String(o.id));if(row){try{note=JSON.parse(String(row.payload||'{}'))}catch{}}}}catch{}if(note&&note.type==='delivery_note'){window.printHtml((note.labels&&note.labels.title)||'送货单',window.deliveryNoteHtml(note),note.paper);return}let body='<div class="print-form"><h1>'+esc((A.site&&A.site.print_title)||'送货单')+'</h1><p>单号：<b>'+esc(o.order_no)+'</b>　状态：'+esc(statusLabel(o.status))+'　出单：'+esc(printLabel(o.print_status))+'</p><p>客户：'+esc(o.customer_snapshot||((o.company||'')+' '+(o.display_name||'')))+'　等级：'+esc(o.level||'')+'　时间：'+esc(fmt(o.created_at))+'</p><p>来源：'+esc(o.source||'客户下单')+'　操作：'+esc(o.operator_name||'客户自助')+'　付款：'+esc(o.pay_method||'')+'</p><table><thead><tr><th>商品</th><th>实发数量</th><th>计价数量</th><th>单价</th><th>小计</th><th>规则备注</th></tr></thead><tbody>';for(const x of j.items||[]){body+='<tr><td>'+esc(x.name)+'</td><td>'+Number(x.qty||0)+'</td><td>'+Number(x.charge_qty||x.qty||0)+'</td><td>'+money(x.unit_price_cents)+'</td><td>'+money(x.line_total_cents)+'</td><td>'+esc(x.rule_note||'')+(Number(x.gift_qty||0)?'（赠 '+x.gift_qty+'）':'')+'</td></tr>'}body+='</tbody></table><p class="big right">合计：'+money(o.total_cents)+'　已付：'+money(o.paid_cents)+'</p><p class="muted">备注：'+esc(o.note||'')+'</p></div>';printHtml('订单明细 '+o.order_no,body)}

let TBL_SEQ=0;const TBL={};
function tbl(headers,rows,opt){const id='t'+(++TBL_SEQ);const o=typeof opt==='string'?{empty:opt}:opt||{};const size=Math.max(3,Number(A.site.table_page_size||8));TBL[id]={headers,rows:rows||[],page:1,all:false,size,empty:o.empty||'暂无数据'};if(Object.keys(TBL).length>80)for(const k of Object.keys(TBL).slice(0,40))delete TBL[k];setTimeout(()=>drawTable(id),0);return '<div class="table-box" id="'+id+'"><div class="tbl-wrap"><table class="tbl"><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody data-tbody></tbody></table></div><div class="pager" data-pager></div></div>'}
function drawTable(id){const box=document.getElementById(id),s=TBL[id];if(!box||!s)return;if(s.bind)setTimeout(()=>{try{s.bind(box)}catch(e){console.error(e)}},0);const total=s.rows.length,pages=Math.max(1,Math.ceil(total/s.size)),page=Math.min(s.page,pages),start=(page-1)*s.size,view=s.all?s.rows:s.rows.slice(start,start+s.size);const tb=box.querySelector('[data-tbody]');tb.innerHTML=view.length?view.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+s.headers.length+'" class="empty">'+esc(s.empty)+'</td></tr>';const pg=box.querySelector('[data-pager]');if(total<=s.size&&!s.all){pg.innerHTML='<span class="hint">共 '+total+' 条</span>';return}pg.innerHTML='<button class="btn ghost sm" data-tpage="prev" data-tid="'+id+'" '+(page<=1?'disabled':'')+'>上页</button><span>第 '+page+' / '+pages+' 页 · 共 '+total+' 条</span><button class="btn ghost sm" data-tpage="next" data-tid="'+id+'" '+(page>=pages?'disabled':'')+'>下页</button><button class="btn ghost sm" data-tall="1" data-tid="'+id+'">'+(s.all?'自动折叠':'显示全部')+'</button>';s.page=page}
function drawAllTables(){Object.keys(TBL).forEach(drawTable)}
let GRID_SEQ=0;const GRID={};
function pagerHtml(id,s,type){const total=s.rows?s.rows.length:s.cards.length,pages=Math.max(1,Math.ceil(total/s.size)),page=Math.min(s.page,pages),attr=(type||'t')==='g'?'g':'t';if(total<=s.size&&!s.all)return '<span class="hint">共 '+total+' 条</span>';return '<button class="btn ghost sm" data-'+attr+'page="prev" data-'+attr+'id="'+id+'" '+(page<=1?'disabled':'')+'>上页</button><span>第 '+page+' / '+pages+' 页 · 共 '+total+' 条</span><button class="btn ghost sm" data-'+attr+'page="next" data-'+attr+'id="'+id+'" '+(page>=pages?'disabled':'')+'>下页</button><button class="btn ghost sm" data-'+attr+'all="1" data-'+attr+'id="'+id+'">'+(s.all?'自动折叠':'显示全部')+'</button>'}
function pagedCards(cards,opt){const id='g'+(++GRID_SEQ),size=Math.max(3,Number(A.site.table_page_size||8));GRID[id]={cards:cards||[],page:1,all:false,size,bind:opt&&opt.bind};if(Object.keys(GRID).length>50)for(const k of Object.keys(GRID).slice(0,25))delete GRID[k];setTimeout(()=>{drawCards(id);if(GRID[id]&&GRID[id].bind)GRID[id].bind()},0);return '<div class="cards-box" id="'+id+'"><div class="product-grid" data-cards>'+(cards||[]).join('')+'</div><div class="pager cards-pager" data-gpager>'+pagerHtml(id,GRID[id],'g')+'</div></div>'}
function drawCards(id){const box=document.getElementById(id),s=GRID[id];if(!box||!s)return;const total=s.cards.length,pages=Math.max(1,Math.ceil(total/s.size)),page=Math.min(s.page,pages),start=(page-1)*s.size,view=s.all?s.cards:s.cards.slice(start,start+s.size);box.querySelector('[data-cards]').innerHTML=view.join('')||'<div class="empty">暂无商品</div>';box.querySelector('[data-gpager]').innerHTML=pagerHtml(id,s,'g');s.page=page;if(s.bind)s.bind()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-tpage],[data-tall],[data-gpage],[data-gall],[data-print-order]');if(!b)return;if(b.dataset.gid){const s=GRID[b.dataset.gid];if(!s)return;if(b.dataset.gpage==='prev')s.page=Math.max(1,s.page-1);if(b.dataset.gpage==='next')s.page++;if(b.dataset.gall)s.all=!s.all;drawCards(b.dataset.gid);return}if(b.dataset.tid){const s=TBL[b.dataset.tid];if(!s)return;if(b.dataset.tpage==='prev')s.page=Math.max(1,s.page-1);if(b.dataset.tpage==='next')s.page++;if(b.dataset.tall)s.all=!s.all;drawTable(b.dataset.tid);return}if(b.dataset.printOrder){printOrder(b.dataset.printOrder,b.dataset.scope||'admin').catch(x=>toast(x.message,'err'))}});

function renderLogin(){const last=sessionStorage.getItem('qdt_login_username')||'';$('#app').innerHTML='<div class="login"><div class="login-art"><div class="brand"><img src="/logo.svg"><div><b>'+APP.name+'</b><span>'+APP.subtitle+'</span></div></div><div><h1>渠道订货，清爽高效</h1><p>登录后可浏览零售 / 渠道 / 核心价格，快速勾选商品加入购物车，一键提交订单。价格、库存、通知实时同步。</p><ul><li>✓ 每个公司独立账号与账单</li><li>✓ 购物车、阶梯价、买赠、退换货</li><li>✓ 超期款项自动锁定</li><li>✓ 新订单自动打印</li></ul></div><div>安全登录 · 私有化部署 · v'+APP.version+'</div></div><div class="login-box"><form class="login-card" id="login"><img src="/logo.svg"><h2>账号登录</h2><p class="muted">首次登录请使用管理员分配的账号和临时密码；登录后仅需修改初始密码，用户名不可自行更改。</p><div class="field"><label>账号</label><input name="username" value="'+esc(last||'')+'" autocomplete="username"></div><div class="field"><label>密码</label><input name="password" type="password" value="" autocomplete="current-password"></div><button class="btn" style="width:100%;margin-top:12px">进入系统</button><p class="hint" style="margin-top:12px">只有后台开通的账号才能进入报价订货系统。</p></form></div></div>';$('#login').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const j=await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:f.get('username'),password:f.get('password')})});sessionStorage.setItem('qdt_login_username',String(f.get('username')||''));sessionStorage.setItem('qdt_fresh_login','1');A.user=j.user;A.csrf=j.csrf||'';await loadMe();await afterLogin()}catch(err){if(err&&err.locked){let mask=document.createElement('div');mask.className='modal-mask qdt-lock-pop';mask.innerHTML='<div class="modal"><h2>'+esc(err.title||'账号已暂停使用')+'</h2><div style="font-size:15px;line-height:1.8;white-space:pre-wrap">'+esc(err.reason||err.message||'账号暂不可登录')+'</div><div class="toolbar" style="margin-top:16px;justify-content:flex-end"><button class="btn ghost" data-close>关闭</button></div></div>';document.body.appendChild(mask);mask.querySelector('[data-close]').onclick=()=>mask.remove();mask.onclick=e=>{if(e.target===mask)mask.remove()}}else toast(err.message,'err')}}}
function forceInitialPassword(){const mask=document.createElement('div');mask.className='modal-mask forced';mask.innerHTML='<div class="modal"><h2>首次登录 · 请修改初始密码</h2><p class="hint">登录账号 <b>'+esc(A.user.username)+'</b> 由管理员分配，<b>用户名不可修改</b>；用户名用于订单、账单和结账归属。请只设置自己的新密码，保存后用原账号重新登录。</p><div class="field"><label>当前临时密码</label><input id="fc_old" type="password"></div><div class="field"><label>新密码（至少 6 位）</label><input id="fc_pw" type="password"></div><div class="field"><label>确认新密码</label><input id="fc_pw2" type="password"></div><button class="btn" id="fc_ok" style="width:100%;margin-top:12px">保存并重新登录</button></div>';document.body.appendChild(mask);$('#fc_ok').onclick=async()=>{try{const j=await api('/api/auth/change-credentials',{method:'POST',body:JSON.stringify({old_password:$('#fc_old').value,new_password:$('#fc_pw').value,new_password2:$('#fc_pw2').value})});sessionStorage.setItem('qdt_login_username',j.username);sessionStorage.removeItem('qdt_fresh_login');toast('初始密码已修改，请用原账号和新密码重新登录','ok');setTimeout(()=>location.reload(),700)}catch(e){toast(e.message,'err')}}}
async function afterLogin(){if(A.user&&A.user.role==='customer'&&Number(A.user.must_change_credentials||0)===1){const fresh=sessionStorage.getItem('qdt_fresh_login')==='1';sessionStorage.removeItem('qdt_fresh_login');if(!fresh){try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}A.user=null;A.csrf='';if(A.evt){A.evt.close();A.evt=null}if(A.poll){clearInterval(A.poll);A.poll=null}renderLogin();return}renderShell();forceInitialPassword();return}navigate(A.user.role==='customer'?'home':(can('ai_report:view')||can('dashboard:view')?'ai_screen':'dashboard'));startLive();if(A.user.role==='customer')setTimeout(showLivePopups,600)}
