function renderShell(){const items=currentNav();$('#app').innerHTML='<div class="shell"><aside class="side"><div class="brand"><img src="/logo.svg"><div><b>'+APP.name+'</b><span>'+APP.subtitle+'</span></div></div><nav class="nav">'+items.map(([k,i,t])=>'<a data-r="'+k+'">'+i+' '+t+'</a>').join('')+'</nav><div class="side-foot">v'+APP.version+' · '+esc(A.user.display_name||A.user.username)+' · '+roleLabel()+'<br><button class="btn ghost sm" style="margin-top:8px" id="logout">退出</button></div></aside><main class="main"><div class="topbar"><h1 id="title"></h1><span class="badge ok" id="live">● 实时同步</span><span class="spacer"></span><span class="badge">'+esc(A.user.level||'核心')+'</span><span class="badge">'+esc(A.user.company||A.user.display_name)+'</span>'+(A.user.role==='customer'?'<button class="btn ghost sm" id="show_pay">💰 收款信息</button>':'')+'</div>'+scrollHtml()+'<div id="page"></div></main></div>';$$('.nav a').forEach(a=>a.onclick=()=>navigate(a.dataset.r));$('#logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});if(A.evt)A.evt.close();if(A.poll)clearInterval(A.poll);A.user=null;sessionStorage.removeItem('qdt_login_username');renderLogin()};if($('#show_pay'))$('#show_pay').onclick=showPaymentInfo}
