function showDuePopup(){const d=A.duePopup;if(!d||!d.summary||d.summary.amount_cents<=0)return;const sig='due|'+String(d.version||'')+'|'+String(d.message||'');if(A.dueSignature===sig||popupHidden(sig))return;A.dueSignature=sig;const html='<div style="font-size:15px;line-height:1.9;white-space:pre-wrap">'+esc(d.message||'')+'</div><div class="grid g2" style="margin-top:12px"><div class="stat"><div class="k">未结账单</div><div class="v">'+d.summary.bill_count+' 笔</div></div><div class="stat"><div class="k">未结金额</div><div class="v money">'+esc(d.summary.amount||'¥0.00')+'</div></div></div><p class="hint">最近到期：'+esc(d.summary.due_date||'—')+'　账期：'+esc(d.summary.payment_days||'')+' 天　<button class="btn ghost sm" id="due_pay">查看收款信息</button></p>';popupHtml(d.title||'账单到期温馨提示',html,'due-pop',{signature:sig});if($('#due_pay'))$('#due_pay').onclick=()=>{$$('.modal-mask.due-pop').forEach(x=>x.remove());showPaymentInfo()}}
function showGlobalPopups(){if(A.popupSeen)return;A.popupSeen=true;const pops=(A.terms&&Array.isArray(A.terms.popups)?A.terms.popups:[]).filter(x=>x&&String(x.content||'').trim());const all=pops.length?pops:(String(A.site.popup_enabled||'0')==='1'&&String(A.site.popup_content||'').trim()?[{title:A.site.popup_title||'系统公告',content:A.site.popup_content||'',image:A.site.popup_image||''}]:[]);let i=0;const next=()=>{if(i>=all.length)return;const x=all[i++];const sig='notice|'+popupSignature(x);if(popupHidden(sig)){setTimeout(next,50);return}const html=(x.image?'<img src="'+esc(x.image)+'" style="width:100%;max-height:280px;object-fit:cover;border-radius:14px;margin-bottom:12px">':'')+'<div style="font-size:15px;line-height:1.8">'+esc(x.content||'')+'</div>';const mask=popupHtml(x.title||'系统公告',html,'notice-pop',{signature:sig});if(mask){mask.querySelector('[data-close]').onclick=()=>{const cb=$('#qdt_popup_hide_today');if(cb&&cb.checked)hidePopupToday(sig);mask.remove();setTimeout(next,120)}}};setTimeout(next,180)}
