async function liveRefresh(){if(!A.user||document.querySelector('.modal-mask.forced'))return;if(['manual','print_settings','products'].includes(A.route)){try{const r=await api('/api/revision');if(r.revision)A.lastRevision=r.revision}catch{};return}try{const r=await api('/api/revision');if(r.revision&&r.revision!==A.lastRevision){A.lastRevision=r.revision;const me=await api('/api/auth/me');const oldScroll=(A.terms&&A.terms.scroll)||'',oldPopupSig=JSON.stringify((A.terms&&A.terms.popups)||[]),oldDue=A.dueSignature;A.user=me.user;A.site=me.site||A.site;A.terms=me.terms||A.terms;A.profile=me.profile||A.profile;A.duePopup=me.due_popup||null;A.perms=me.permissions||A.perms;A.overdueDays=me.overdue_days;A.csrf=me.csrf||A.csrf;const wrap=$('.scroll-wrap');if(wrap)wrap.outerHTML=scrollHtml();if(oldScroll!==((A.terms&&A.terms.scroll)||'')||oldPopupSig!==JSON.stringify((A.terms&&A.terms.popups)||[])){A.popupSeen=false;A.noticeSeen=false}if(A.user.role==='customer'&&A.duePopup){const sig=String(A.duePopup.version||'')+'|'+String(A.duePopup.message||'');if(sig!==oldDue){A.dueSignature='';showDuePopup()}}await renderPage();if(A.user.role==='customer'&&!document.querySelector('.modal-mask'))setTimeout(showGlobalPopups,180)}}catch{}}
function startLive(){if(A.evt)A.evt.close();if(A.poll)clearInterval(A.poll);if(!A.user)return;A.lastRevision=A.lastRevision||1;const es=new EventSource('/api/stream');A.evt=es;['hello','sync','refresh','products','orders','returns','bills','users','settings','notices','prints','restore','due','profile','payment','order','return','cart'].forEach(evt=>es.addEventListener(evt,liveRefresh));const sec=Math.max(1,Number(A.site.live_poll_seconds||3));A.poll=setInterval(liveRefresh,sec*1000)}

function priceRulesText(v){return jparse(v).map(x=>x.min_qty+'='+yuan(x.price_cents)).join(';')}
function giftRulesText(v){return jparse(v).map(x=>x.buy_qty+'送'+x.gift_qty).join(';')}
function calcLocal(p,level,qty){qty=Math.max(1,Math.floor(Number(qty||1)));const key=level==='核心'?'core_cents':level==='渠道'?'channel_cents':'retail_cents';let unit=Number(p[key]||p.retail_cents||0),notes=[];const pr=jparse(p.price_rules).filter(x=>qty>=Number(x.min_qty||0)).sort((a,b)=>Number(b.min_qty)-Number(a.min_qty));if(pr[0]){unit=Number(pr[0].price_cents||0);notes.push('满'+pr[0].min_qty+'件单价'+yuan(unit)+'元')}const gr=jparse(p.gift_rules).filter(x=>qty>=Number(x.buy_qty||0)).sort((a,b)=>Number(b.buy_qty)-Number(a.buy_qty));let gift=0;if(gr[0]){gift=Math.floor(qty/Number(gr[0].buy_qty))*Number(gr[0].gift_qty);notes.push('买'+gr[0].buy_qty+'送'+gr[0].gift_qty+'：实发'+(qty+gift)+'件，按'+qty+'件计价')}return {qty,final_qty:qty+gift,charge_qty:qty,gift_qty:gift,unit_price_cents:unit,line_total_cents:unit*qty,rule_note:notes.join('；')}}
async function loadProducts(){const j=await api('/api/products'+(A.q||A.cat?'?q='+encodeURIComponent(A.q)+'&category='+encodeURIComponent(A.cat):''));A.products=j.rows;A.site=j.site||A.site;return j}
async function pageHome(){const j=await loadProducts();const cats=[...new Set(j.rows.map(x=>x.category).filter(Boolean))];const cards=j.rows.map(p=>'<div class="product-card"><div class="product-img">'+esc(p.category||'商品')+'</div><div class="product-body"><h3>'+esc(p.name)+'</h3><div class="product-meta">'+esc(p.model||p.sku)+'<br>库存 '+p.stock+' '+esc(p.unit||'件')+'</div><div class="price">'+money(p.price_cents)+'</div>'+(p.rule_summary?'<div class="rule-note">'+esc(p.rule_summary)+'</div>':'')+'<div class="qty-row"><input type="number" min="1" max="'+p.stock+'" value="1" id="qty_'+p.id+'"><button class="btn sm" data-add="'+p.id+'">加入购物车</button><button class="btn ghost sm" data-buy="'+p.id+'">立即下单</button></div></div></div>');const bind=()=>{$$('[data-add]').forEach(b=>b.onclick=async()=>{const id=Number(b.dataset.add),qty=Number($('#qty_'+id).value||1);try{await api('/api/cart',{method:'POST',body:JSON.stringify({product_id:id,qty})});toast('已加入购物车','ok');await pageHome()}catch(e){toast(e.message,'err')}});$$('[data-buy]').forEach(b=>b.onclick=async()=>{const id=Number(b.dataset.buy),qty=Number($('#qty_'+id).value||1);try{await api('/api/cart',{method:'POST',body:JSON.stringify({product_id:id,qty})});navigate('cart')}catch(e){toast(e.message,'err')}})};$('#page').innerHTML='<div class="card"><div class="toolbar"><input id="pq" placeholder="搜索名称 / 编码 / 型号" value="'+esc(A.q)+'" style="max-width:320px"><select id="pcat" style="max-width:180px"><option value="">全部分类</option>'+cats.map(c=>'<option '+(A.cat===c?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select><button class="btn ghost" id="pclear">重置</button><span class="spacer"></span><button class="btn" id="go_cart">购物车</button></div><p class="hint">当前等级价格：'+esc(A.user.level)+'；价格、库存、阶梯价、买赠规则实时同步，后台修改无需刷新。</p></div><div style="margin-top:14px">'+pagedCards(cards,{bind})+'</div>';$('#pq').oninput=e=>{A.q=e.target.value};$('#pq').onchange=()=>pageHome();$('#pcat').onchange=e=>{A.cat=e.target.value;pageHome()};$('#pclear').onclick=()=>{A.q='';A.cat='';pageHome()};$('#go_cart').onclick=()=>navigate('cart');bind()}
async function loadCart(){const j=await api('/api/cart');A.cart=j.rows;return j}
async function pageCart(){const j=await loadCart();$('#page').innerHTML='<div class="grid g2"><div class="card"><div class="toolbar"><h2>购物车</h2><span class="spacer"></span><button class="btn ghost sm" id="cart_clear">清空</button></div>'+((j.rows||[]).map(x=>'<div class="cart-item"><div><b>'+esc(x.name)+'</b><div class="hint">'+money(x.unit_price_cents||x.price_cents)+' × '+x.qty+' · 实发 '+x.final_qty+' · 库存 '+x.stock+'</div>'+(x.rule_note?'<div class="rule-note">'+esc(x.rule_note)+'</div>':'')+'</div><input type="number" min="1" max="'+x.stock+'" value="'+x.qty+'" data-cqty="'+x.id+'"><button class="btn ghost sm" data-cdel="'+x.id+'">移除</button></div>').join('')||'<div class="empty">购物车还是空的</div>')+'</div><div class="card cart-panel"><h2>提交订单</h2><div class="stat"><div class="k">订单合计</div><div class="v money">'+money(j.total_cents||0)+'</div></div><div class="sep"></div><div class="field"><label>付款 / 结算方式</label><div class="pay-chips">'+['记账','微信','支付宝','银行转账','现金'].map(x=>'<button class="pay-chip '+(A.pay===x?'on':'')+'" data-pay="'+x+'">'+ck(A.pay===x)+x+'</button>').join('')+'</div></div><div class="field"><label>订单备注</label><textarea id="order_note" rows="3" placeholder="收货信息、开票信息等"></textarea></div><button class="btn" style="width:100%;padding:14px;font-size:17px" id="submit_order">提交订单并生成账单</button><p class="hint">选择「记账」会生成应收款账单，超过 '+(A.overdueDays||30)+' 天未结清将禁止登录，需管理员处理。阶梯价 / 买赠由系统自动计算并写入备注。</p></div></div>';$$('[data-pay]').forEach(b=>b.onclick=()=>{A.pay=b.dataset.pay;pageCart()});$('#cart_clear').onclick=async()=>{await api('/api/cart/clear',{method:'POST',body:'{}'});await pageCart()};$$('[data-cqty]').forEach(i=>i.onchange=async()=>{await api('/api/cart',{method:'POST',body:JSON.stringify({product_id:Number(i.dataset.cqty),qty:Number(i.value)})});await pageCart()});$$('[data-cdel]').forEach(b=>b.onclick=async()=>{await api('/api/cart',{method:'POST',body:JSON.stringify({product_id:Number(b.dataset.cdel),qty:0})});await pageCart()});$('#submit_order').onclick=async()=>{const items=A.cart.map(x=>({product_id:x.id,qty:x.qty}));try{const r=await api('/api/orders',{method:'POST',body:JSON.stringify({items,pay_method:A.pay,note:$('#order_note').value})});A.cart=[];toast('订单 '+r.order_no+' 已提交，购物车已清空','ok');if(r.auto_notes&&r.auto_notes.length)toast('已自动应用：'+r.auto_notes.join('；'),'ok');navigate('myorders')}catch(e){await loadCart();toast(e.message,'err');await pageCart()}}}
async function pageMyOrders(){const j=await api('/api/orders');$('#page').innerHTML='<div class="card"><h2>我的订单</h2>'+tbl(['单号','时间','总额','已付','状态','出单','操作'],j.rows.map(o=>[esc(o.order_no),fmt(o.created_at),money(o.total_cents),money(o.paid_cents),statusBadge(o.status),printBadge(o.print_status),'<button class="btn ghost sm" data-od="'+o.id+'">明细</button> <button class="btn ghost sm" data-print-order="'+o.id+'" data-scope="customer">打印</button> <button class="btn ghost sm" data-rt="'+o.id+'">申请退换货</button>']))+'</div>';drawAllTables();const bind=()=>{$$('[data-od]').forEach(b=>b.onclick=async()=>{const j=await api('/api/orders/'+b.dataset.od);const mask=modal('订单 '+j.order.order_no,'<p>客户：'+esc(A.user.company||A.user.display_name)+'　状态：'+esc(statusLabel(j.order.status))+'　时间：'+fmt(j.order.created_at)+'</p>'+tbl(['商品','实发','计价','单价','小计','规则备注'],j.items.map(x=>[esc(x.name),x.qty,Number(x.charge_qty||x.qty),money(x.unit_price_cents),money(x.line_total_cents),esc(x.rule_note||'')]))+'<div class="toolbar" style="margin-top:12px"><button class="btn ghost sm" id="print_this">打印明细</button></div>');mask.querySelector('#print_this').onclick=()=>printOrder(b.dataset.od,'customer')});$$('[data-rt]').forEach(b=>b.onclick=async()=>{try{const j=await api('/api/orders/'+b.dataset.rt);const rows=j.items.filter(x=>Number(x.qty)>Number(x.returned_qty));if(!rows.length)return toast('该订单没有可退换商品','err');window.__rtChecked=new Set(rows.map(x=>String(x.id)));window.__rtRows=rows;window.__rtQty={};window.__modalBind=()=>{$$('[data-ri]').forEach(c=>{c.checked=window.__rtChecked.has(c.dataset.ri);c.onchange=()=>{if(c.checked)window.__rtChecked.add(c.dataset.ri);else window.__rtChecked.delete(c.dataset.ri)}});$$('[data-rq]').forEach(i=>{i.value=String(window.__rtQty[i.dataset.rq]||i.value||1);i.oninput=()=>{window.__rtQty[i.dataset.rq]=i.value}})};modal('申请退换货 · 可多选商品','<div class="field"><label>类型</label><select id="rt_kind"><option>退货</option><option>换货</option></select></div><div class="field"><label>原因</label><input id="rt_reason" placeholder="例如：型号不符 / 质量问题"></div>'+tbl(['选择','商品','可退数量','本次数量','单价'],rows.map(x=>['<input type="checkbox" checked data-ri="'+x.id+'" style="width:auto">',esc(x.name),Number(x.qty)-Number(x.returned_qty),'<input type="number" min="1" max="'+(Number(x.qty)-Number(x.returned_qty))+'" value="1" data-rq="'+x.id+'">',money(x.unit_price_cents)]))+'<div class="field"><label>备注</label><input id="rt_note"></div>',async()=>{const items=[];$$('[data-rq]').forEach(i=>{window.__rtQty=window.__rtQty||{};window.__rtQty[i.dataset.rq]=i.value});for(const id of window.__rtChecked||[]){const q=Number(String(window.__rtQty&&window.__rtQty[id]||1));if(q>0)items.push({order_item_id:Number(id),qty:q})}if(!items.length)throw new Error('请选择商品并填写数量');await api('/api/returns',{method:'POST',body:JSON.stringify({kind:$('#rt_kind').value,reason:$('#rt_reason').value,note:$('#rt_note').value,items})});toast('退换货申请已提交','ok');navigate('myreturns')})}catch(e){toast(e.message,'err')}})};bind()}
async function pageMyReturns(){const j=await api('/api/returns');$('#page').innerHTML='<div class="card"><h2>退换货申请</h2>'+tbl(['单号','关联订单','类型','金额','状态','原因','时间'],j.rows.map(r=>[esc(r.return_no),esc(r.order_no||'—'),esc(r.kind),money(r.total_cents),'<span class="badge '+(r.status==='已通过'?'ok':r.status==='已拒绝'?'err':'warn')+'">'+esc(r.status)+'</span>',esc(r.reason),fmt(r.created_at)]))+'</div>'}
async function pageMyBills(){const j=await api('/api/bills');$('#page').innerHTML='<div class="grid g4"><div class="stat"><div class="k">账单总额</div><div class="v money">'+money(j.finance.total_cents)+'</div></div><div class="stat"><div class="k">已结</div><div class="v money">'+money(j.finance.paid_cents)+'</div></div><div class="stat warn"><div class="k">未结</div><div class="v money">'+money(j.finance.balance_cents)+'</div></div><div class="stat"><div class="k">退货总额</div><div class="v money">'+money(j.finance.return_total_cents)+'</div></div></div><div class="card" style="margin-top:14px"><h2>账单明细</h2><p class="hint">超期规则：账龄达到或超过 '+j.overdue_days+' 天且未结清，账号将无法登录，需联系管理员处理。</p>'+tbl(['账单号','来源','总额','已付','未结','到期日','账龄','状态'],j.rows.map(b=>[esc(b.bill_no),esc(b.source_type),money(b.total_cents),money(b.paid_cents),money(b.balance_cents),esc(b.due_at),(b.age_days+' 天')+(b.overdue?' <span class="badge err">超期</span>':''),esc(b.status)]))+'</div>'}
async function pageMine(){const [me,reqs]=await Promise.all([api('/api/auth/me'),api('/api/company-change')]);const u=me.user,rows=reqs.rows||[];$('#page').innerHTML='<div class="grid g2"><div class="card"><h2>账号资料</h2><p><b>'+esc(u.display_name)+'</b>　'+esc(u.level)+'　'+esc(u.company||'')+'</p><p class="hint">登录账号：<b>'+esc(u.username)+'</b>（不可修改；订单、账单、结账均按该账号归属）　手机：'+esc(u.phone||'—')+'</p><div class="sep"></div><p>未结金额：<b>'+money(u.finance.balance_cents)+'</b>　<button class="btn ghost sm" id="mine_pay">查看收款信息</button>　超期规则：'+me.overdue_days+' 天</p></div><div class="card"><h2>修改密码</h2><p class="hint">仅修改密码，不会改变登录账号。</p><div class="field"><label>原密码</label><input type="password" id="opw"></div><div class="field"><label>新密码</label><input type="password" id="npw"></div><div class="field"><label>确认新密码</label><input type="password" id="npw2"></div><button class="btn" id="pw_save">保存密码</button></div></div><div class="grid g2" style="margin-top:14px"><div class="card"><h2>公司名称变更申请</h2><p class="hint">公司名称提交后不会立即生效，需管理员审核通过；登录账号不变，历史订单和账单归属不变。</p><div class="field"><label>当前公司名称</label><input value="'+esc(u.company||'')+'" disabled></div><div class="field"><label>申请变更为</label><input id="cc_new" placeholder="例如：某某电脑有限公司"></div><div class="field"><label>变更说明</label><textarea id="cc_reason" rows="3" placeholder="可选：营业执照变更 / 开票信息变更"></textarea></div><button class="btn" id="cc_submit">提交管理员审核</button></div><div class="card"><h2>我的申请记录</h2>'+tbl(['提交时间','原公司','申请公司','状态','说明','审核备注'],rows.map(x=>[fmt(x.created_at),esc(x.old_company||'—'),esc(x.new_company),esc(x.status),esc(x.reason||''),esc(x.review_note||'')]))+'</div></div>';if($('#mine_pay'))$('#mine_pay').onclick=showPaymentInfo;$('#pw_save').onclick=async()=>{await api('/api/auth/password',{method:'POST',body:JSON.stringify({old_password:$('#opw').value,new_password:$('#npw').value,new_password2:$('#npw2').value})});sessionStorage.setItem('qdt_login_username',u.username);toast('密码已修改，请用原账号重新登录','ok');setTimeout(()=>location.reload(),700)};$('#cc_submit').onclick=async()=>{await api('/api/company-change',{method:'POST',body:JSON.stringify({new_company:$('#cc_new').value,reason:$('#cc_reason').value})});toast('已提交，等待管理员审核','ok');await pageMine()};drawAllTables()}

async function pageAdminDashboard(){const j=await api('/api/admin/dashboard'),s=j.stats;$('#page').innerHTML='<div class="grid g4"><div class="stat"><div class="k">客户数</div><div class="v">'+s.user_count+'</div></div><div class="stat"><div class="k">商品 / 低库存</div><div class="v">'+s.product_count+' / '+s.low_stock+'</div></div><div class="stat"><div class="k">订单 / 待审退货</div><div class="v">'+s.order_count+' / '+s.return_pending+'</div></div><div class="stat"><div class="k">未结款项</div><div class="v money">'+money(s.unpaid_cents)+'</div></div></div><div class="grid g2" style="margin-top:14px"><div class="card"><h3>最近订单</h3>'+tbl(['单号','客户','金额','状态','出单','时间'],j.recentOrders.map(o=>[esc(o.order_no),esc(o.company||o.display_name),money(o.total_cents),statusBadge(o.status),printBadge(o.print_status),fmt(o.created_at)]))+'</div><div class="card"><h3>待处理退货</h3>'+tbl(['单号','客户','金额','状态'],j.recentReturns.map(r=>[esc(r.return_no),esc(r.company||r.display_name),money(r.total_cents),esc(r.status)]))+'</div></div><div class="grid g2" style="margin-top:14px"><div class="card"><h3>客户订货排行</h3>'+tbl(['客户','公司','订单数','订货额'],j.topCustomers.map(x=>[esc(x.display_name),esc(x.company||'—'),x.order_count,money(x.total_cents)]))+'</div><div class="card"><h3>超期账单</h3>'+tbl(['账单','客户','未结','账龄'],j.overdue.map(x=>[esc(x.bill_no),esc(x.company||x.display_name),money(x.balance_cents),x.age_days+' 天']))+'</div></div>'}
async function pageAdminProducts(){const j=await api('/api/admin/products');$('#page').innerHTML='<div class="card"><div class="toolbar"><h2>商品库存与价格</h2><span class="spacer"></span><button class="btn ghost sm" id="prod_tpl">下载模板</button><input type="file" id="prod_file" accept=".csv" style="max-width:220px"><button class="btn ghost sm" id="prod_import">导入 CSV</button>'+(can('product:manage')?'<button class="btn" id="prod_new">＋ 新增商品</button>':'')+'</div><p class="hint">价格 / 库存 / 阶梯价 / 买赠保存后，前台实时同步，无需刷新。规则示例：阶梯价「5=28;10=26」，买赠「10送1」。</p>'+tbl(['编码','名称','分类','零售','渠道','核心','库存','规则','状态','操作'],j.rows.map(p=>[esc(p.sku),esc(p.name),esc(p.category),yuan(p.retail_cents),yuan(p.channel_cents),yuan(p.core_cents),p.stock,esc(ruleSummaryText(p)),esc(p.status),can('product:manage')?'<button class="btn ghost sm" data-pe="'+p.id+'">编辑</button>':'—']))+'</div>';$('#prod_tpl').onclick=()=>{const a=document.createElement('a');a.href='data:text/csv;charset=utf-8,'+encodeURIComponent('\ufeff编码,名称,型号,分类,单位,零售价,渠道价,核心价,库存,状态,阶梯价,买赠\nPJ-2001,示例商品,型号A,办公设备,台,199.00,179.00,159.00,20,上架,5=180;10=160,10送1\n');a.download='qudingtong-products.csv';a.click()};$('#prod_import').onclick=async()=>{const f=$('#prod_file').files[0];if(!f)return toast('请先选择 CSV 文件','err');const grid=parseCsvText(await f.text());if(grid.length<2)return toast('CSV 没有数据行','err');const h=grid[0].map(x=>String(x).trim()),norm=x=>String(x||'').toLowerCase().replace(/[\s_-]/g,''),idx=(...names)=>h.findIndex(x=>names.some(n=>norm(x)===norm(n)||norm(x).includes(norm(n))));const map={sku:idx('编码','sku'),name:idx('名称','name'),model:idx('型号','model'),category:idx('分类','category'),unit:idx('单位','unit'),retail:idx('零售价','retail'),channel:idx('渠道价','channel'),core:idx('核心价','core'),stock:idx('库存','stock'),safe_stock:idx('安全库存'),status:idx('状态','status'),description:idx('说明','description'),price_rules:idx('阶梯价','价格规则'),gift_rules:idx('买赠','赠送规则')};if(map.name<0||map.retail<0||map.channel<0||map.core<0)return toast('CSV 表头需包含 名称、零售价、渠道价、核心价','err');const rows=grid.slice(1).filter(r=>r.some(x=>String(x||'').trim())).map(r=>{const v=k=>map[k]>=0?String(r[map[k]]??'').trim():'';return {sku:v('sku'),name:v('name'),model:v('model'),category:v('category'),unit:v('unit'),retail:v('retail'),channel:v('channel'),core:v('core'),stock:v('stock'),safe_stock:v('safe_stock'),status:v('status'),description:v('description'),price_rules:v('price_rules'),gift_rules:v('gift_rules')}});const j2=await api('/api/admin/import/products',{method:'POST',body:JSON.stringify({rows})});toast('导入完成：成功 '+j2.success+'，失败 '+j2.failed,'ok');await pageAdminProducts()};if($('#prod_new'))$('#prod_new').onclick=()=>productModal({},pageAdminProducts);$$('[data-pe]').forEach(b=>b.onclick=()=>productModal(j.rows.find(x=>String(x.id)===b.dataset.pe),pageAdminProducts))}
function ruleSummaryText(p){const a=[];for(const x of jparse(p.price_rules))a.push('满'+x.min_qty+'件 '+yuan(x.price_cents)+'元');for(const x of jparse(p.gift_rules))a.push('买'+x.buy_qty+'送'+x.gift_qty);return a.join('；')}
function productModal(p,refresh){const f=(k,d='')=>esc(p[k]??d);modal(p.id?'编辑商品':'新增商品','<input type="hidden" id="pid" value="'+(p.id||'')+'"><div class="grid g2"><div class="field"><label>编码</label><input id="f_sku" value="'+f('sku')+'"></div><div class="field"><label>名称</label><input id="f_name" value="'+f('name')+'"></div><div class="field"><label>型号</label><input id="f_model" value="'+f('model')+'"></div><div class="field"><label>分类</label><input id="f_category" value="'+f('category','未分类')+'"></div><div class="field"><label>单位</label><input id="f_unit" value="'+f('unit','件')+'"></div><div class="field"><label>状态</label><select id="f_status"><option '+(p.status==='上架'?'selected':'')+'>上架</option><option '+(p.status==='下架'?'selected':'')+'>下架</option></select></div><div class="field"><label>零售价（元）</label><input id="f_retail" value="'+(p.retail_cents?yuan(p.retail_cents):'')+'"></div><div class="field"><label>渠道价（元）</label><input id="f_channel" value="'+(p.channel_cents?yuan(p.channel_cents):'')+'"></div><div class="field"><label>核心价（元）</label><input id="f_core" value="'+(p.core_cents?yuan(p.core_cents):'')+'"></div><div class="field"><label>库存</label><input type="number" id="f_stock" value="'+(p.stock??0)+'"></div><div class="field"><label>安全库存</label><input type="number" id="f_safe" value="'+(p.safe_stock??0)+'"></div><div class="field"><label>图片链接</label><input id="f_image" value="'+f('image')+'"></div><div class="field"><label>阶梯价规则</label><input id="f_price_rules" value="'+esc(priceRulesText(p.price_rules))+'" placeholder="5=28;10=26"></div><div class="field"><label>买赠规则</label><input id="f_gift_rules" value="'+esc(giftRulesText(p.gift_rules))+'" placeholder="10送1"></div></div><div class="field"><label>说明</label><textarea id="f_desc" rows="3">'+f('description')+'</textarea></div>',async()=>{const v=k=>$('#f_'+k).value;const cents=x=>Math.round(Number(x||0)*100);const body={sku:v('sku'),name:v('name'),model:v('model'),category:v('category'),unit:v('unit'),status:v('status'),retail_cents:cents(v('retail')),channel_cents:cents(v('channel')),core_cents:cents(v('core')),stock:Number(v('stock')),safe_stock:Number(v('safe')),image:v('image'),description:v('desc'),price_rules:v('price_rules'),gift_rules:v('gift_rules')};if(!body.name)throw new Error('名称不能为空');await api(p.id?'/api/admin/products/'+p.id:'/api/admin/products',{method:p.id?'PUT':'POST',body:JSON.stringify(body)});toast('商品已保存','ok');await refresh()})}
async function pageAdminOrders(){const j=await api('/api/admin/orders');$('#page').innerHTML='<div class="card"><div class="toolbar"><h2>订单管理</h2><span class="spacer"></span><a class="btn ghost sm" href="/api/admin/export/orders.csv">导出 CSV</a></div>'+tbl(['单号','客户','来源','总额','已付','状态','出单','时间','操作'],j.rows.map(o=>[esc(o.order_no),esc(o.customer_snapshot||o.company||o.display_name),esc(o.source||'客户下单'),money(o.total_cents),money(o.paid_cents),statusBadge(o.status),printBadge(o.print_status),fmt(o.created_at),'<button class="btn ghost sm" data-ao="'+o.id+'">明细</button> <button class="btn ghost sm" data-print-order="'+o.id+'" data-scope="admin">打印</button>']))+'</div>';$$('[data-ao]').forEach(b=>b.onclick=async()=>{const j=await api('/api/admin/orders/'+b.dataset.ao);const mask=modal('订单 '+j.order.order_no,'<p>'+esc(j.order.customer_snapshot||((j.order.company||'')+' '+(j.order.display_name||'')))+'　'+esc(j.order.level||'')+'　'+esc(statusLabel(j.order.status))+'　'+fmt(j.order.created_at)+'</p><p class="hint">来源：'+esc(j.order.source||'客户下单')+'　操作：'+esc(j.order.operator_name||'客户自助')+'　付款：'+esc(j.order.pay_method||'')+'</p>'+tbl(['商品','实发','计价','单价','小计','规则备注'],j.items.map(x=>[esc(x.name),x.qty,Number(x.charge_qty||x.qty),money(x.unit_price_cents),money(x.line_total_cents),esc(x.rule_note||'')]))+'<p class="hint">订单备注：'+esc(j.order.note||'')+'</p>'+(can('order:manage')?'<div class="toolbar" style="margin-top:14px"><select id="ost">'+['成功','已发货','已完成','已取消'].map(s=>'<option '+(statusLabel(j.order.status)===s?'selected':'')+'>'+s+'</option>').join('')+'</select><button class="btn sm" id="osave">更新状态</button></div>':'')+'<div class="toolbar" style="margin-top:12px"><button class="btn ghost sm" id="print_this">打印明细</button></div>');mask.querySelector('#print_this').onclick=()=>printOrder(b.dataset.ao,'admin');if($('#osave'))$('#osave').onclick=async()=>{await api('/api/admin/orders/'+j.order.id+'/status',{method:'POST',body:JSON.stringify({status:$('#ost').value})});toast('状态已更新','ok');mask.remove();await pageAdminOrders()}})}
async function pageAdminReturns(){const j=await api('/api/admin/returns');$('#page').innerHTML='<div class="card"><h2>退货审核</h2>'+tbl(['单号','订单','客户','类型','金额','状态','原因','操作'],j.rows.map(r=>[esc(r.return_no),esc(r.order_no||'—'),esc(r.company||r.display_name),esc(r.kind),money(r.total_cents),'<span class="badge '+(r.status==='已通过'?'ok':r.status==='已拒绝'?'err':'warn')+'">'+esc(r.status)+'</span>',esc(r.reason),r.status==='待审核'&&can('return:review')?'<button class="btn ok sm" data-rok="'+r.id+'">通过</button> <button class="btn warn sm" data-rno="'+r.id+'">拒绝</button>':'—']))+'</div>';const review=async(id,d)=>{await api('/api/admin/returns/'+id+'/review',{method:'POST',body:JSON.stringify({decision:d})});toast('已处理，前台会实时同步','ok');await pageAdminReturns()};$$('[data-rok]').forEach(b=>b.onclick=()=>review(b.dataset.rok,'approve'));$$('[data-rno]').forEach(b=>b.onclick=()=>review(b.dataset.rno,'reject'))}
async function pageAdminBills(){const j=await api('/api/admin/bills');$('#page').innerHTML='<div class="card"><h2>账单财务</h2><p class="hint">超期 '+j.overdue_days+' 天（含 '+j.overdue_days+' 天）未结清账号会自动禁止登录，管理员可在客户管理里解锁。</p>'+tbl(['账单','客户','来源','总额','已付','未结','账龄','状态','操作'],j.rows.map(b=>[esc(b.bill_no),esc(b.company||b.display_name),esc(b.source_type),money(b.total_cents),money(b.paid_cents),money(b.balance_cents),(b.age_days+' 天')+(b.overdue?' <span class="badge err">超期</span>':''),esc(b.status),Number(b.balance_cents)>0&&can('bill:manage')?'<button class="btn sm" data-paybill="'+b.id+'" data-max="'+b.balance_cents+'">收款</button>':'—']))+'</div>';$$('[data-paybill]').forEach(b=>b.onclick=()=>{const max=Number(b.dataset.max)/100;modal('账单收款','<div class="field"><label>收款金额（元，最多 '+max.toFixed(2)+'）</label><input id="pay_amt" value="'+max.toFixed(2)+'"></div><div class="field"><label>方式</label><select id="pay_m">'+['现金','微信','支付宝','银行转账','记账'].map(x=>'<option>'+x+'</option>').join('')+'</select></div><div class="field"><label>备注</label><input id="pay_note"></div>',async()=>{await api('/api/admin/bills/payment',{method:'POST',body:JSON.stringify({bill_id:Number(b.dataset.paybill),amount:$('#pay_amt').value,pay_method:$('#pay_m').value,note:$('#pay_note').value})});toast('收款已登记','ok');await pageAdminBills()})})}
async function pageAdminCustomers(){const j=await api('/api/admin/users');$('#page').innerHTML='<div class="card"><div class="toolbar"><h2>客户账号管理</h2><span class="spacer"></span>'+(can('customer:manage')?'<button class="btn" id="user_new">＋ 开通账号</button>':'')+'</div>'+tbl(['账号','名称','公司','等级','额度','未结','状态','操作'],j.rows.map(u=>[esc(u.username),esc(u.display_name),esc(u.company||'—'),esc(u.level),money(u.credit_limit_cents),money(u.finance.balance_cents),(u.active?'启用':'停用')+' / '+(u.overdue_lock?'<span class="badge err">锁定</span>':'正常')+(u.must_change_credentials?' <span class="badge warn">待改初始密码</span>':''),can('customer:manage')?'<button class="btn ghost sm" data-ue="'+u.id+'">编辑</button> <button class="btn ghost sm" data-ur="'+u.id+'">重置临时密码</button> <button class="btn '+(u.locked?'ok':'warn')+' sm" data-ul="'+u.id+'" data-lock="'+(u.locked?0:1)+'">'+(u.locked?'解锁':'锁定')+'</button> <button class="btn warn sm" data-ud="'+u.id+'">删除</button>':'—']))+'</div>';$$('[data-ue]').forEach(b=>b.onclick=()=>userModal(j.rows.find(x=>String(x.id)===b.dataset.ue),pageAdminCustomers));$$('[data-ur]').forEach(b=>b.onclick=()=>resetUserModal(j.rows.find(x=>String(x.id)===b.dataset.ur),pageAdminCustomers));if($('#user_new'))$('#user_new').onclick=()=>userModal({},pageAdminCustomers);$$('[data-ul]').forEach(b=>b.onclick=async()=>{await api('/api/admin/users/'+b.dataset.ul,{method:'PUT',body:JSON.stringify({locked:Number(b.dataset.lock),lock_reason:Number(b.dataset.lock)?'管理员锁定':''})});toast('已更新','ok');await pageAdminCustomers()});$$('[data-ud]').forEach(b=>b.onclick=async()=>{if(!confirm('确认删除该客户？仅无订单、账单、退货、收款记录的客户可删除。'))return;try{await api('/api/admin/users/'+b.dataset.ud,{method:'DELETE',body:'{}'});toast('客户已删除','ok');await pageAdminCustomers()}catch(e){toast(e.message,'err')}})}
function userModal(u,refresh){modal(u.id?'编辑客户':'开通客户账号','<input type="hidden" id="uid" value="'+(u.id||'')+'"><div class="grid g2"><div class="field"><label>登录账号（客户不可自行修改）</label><input id="u_username" value="'+esc(u.username||'')+'"></div><div class="field"><label>显示名称</label><input id="u_display" value="'+esc(u.display_name||'')+'"></div><div class="field"><label>密码 '+(u.id?'（留空不改）':'')+'</label><input id="u_password" type="password" value=""></div><div class="field"><label>客户等级</label><select id="u_level">'+['零售','渠道','核心'].map(x=>'<option '+(u.level===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="field"><label>账期天数（0-365；0=现结，留空用全站默认）</label><input id="u_days" type="number" min="0" max="365" value="'+esc(u.payment_days||'')+'"></div><div class="field"><label>公司</label><input id="u_company" value="'+esc(u.company||'')+'"></div><div class="field"><label>联系人</label><input id="u_contact" value="'+esc(u.contact||'')+'"></div><div class="field"><label>电话</label><input id="u_phone" value="'+esc(u.phone||'')+'"></div><div class="field"><label>授信额度（元）</label><input id="u_credit" value="'+yuan(u.credit_limit_cents||0)+'"></div></div><div class="field"><label>地址</label><input id="u_address" value="'+esc(u.address||'')+'"></div><label class="hint"><input type="checkbox" id="u_force" style="width:auto" '+(!u.id||u.must_change_credentials?'checked':'')+'> 下次登录强制修改初始密码（用户名不变）</label>',async()=>{const days=String($('#u_days').value||'').trim();const body={username:$('#u_username').value,display_name:$('#u_display').value,password:$('#u_password').value,level:$('#u_level').value,company:$('#u_company').value,contact:$('#u_contact').value,phone:$('#u_phone').value,address:$('#u_address').value,credit_limit_cents:Math.round(Number($('#u_credit').value||0)*100),active:1,must_change_credentials:$('#u_force').checked?1:0};if(days)body.payment_days=Number(days);if(!u.id&&!body.password)body.password='User@8282';await api(u.id?'/api/admin/users/'+u.id:'/api/admin/users',{method:u.id?'PUT':'POST',body:JSON.stringify(body)});toast('客户已保存','ok');await refresh()})}
function resetUserModal(u,refresh){modal('重置临时密码 · '+esc(u.display_name),'<p class="hint">当前账号 <b>'+esc(u.username)+'</b> 不会改变。设置临时密码后，客户必须用原账号登录并修改初始密码才能下单；用户名仍用于订单、账单与结账归属。</p><div class="field"><label>临时密码（至少 6 位）</label><input id="ru_pw" value="User@8282"></div><p class="hint">保存后会自动要求客户登录后修改初始密码。</p>',async()=>{await api('/api/admin/users/'+u.id,{method:'PUT',body:JSON.stringify({password:$('#ru_pw').value,must_change_credentials:1})});toast('临时密码已重置','ok');await refresh()})}
async function pageAdminStaff(){const [j,p]=await Promise.all([api('/api/admin/staff'),api('/api/admin/permissions')]);$('#page').innerHTML='<div class="card"><div class="toolbar"><h2>员工与权限</h2><span class="spacer"></span><button class="btn" id="staff_new">＋ 新增员工</button></div><p class="hint">员工登录后按权限显示菜单；管理员默认拥有全部权限。默认员工：staff / Staff@8282。</p>'+tbl(['账号','名称','权限数','状态','操作'],j.rows.map(u=>[esc(u.username),esc(u.display_name),(u.permissions||[]).length,(u.active?'启用':'停用')+(u.locked?' / 锁定':''),'<button class="btn ghost sm" data-se="'+u.id+'">编辑权限</button>']))+'</div>';if($('#staff_new'))$('#staff_new').onclick=()=>staffModal({},p.permissions,j.rows,pageAdminStaff);$$('[data-se]').forEach(b=>b.onclick=()=>staffModal(j.rows.find(x=>String(x.id)===b.dataset.se),p.permissions,j.rows,pageAdminStaff))}
function staffModal(u,perms,rows,refresh){const selected=u.permissions||[];modal(u.id?'编辑员工权限':'新增员工','<div class="grid g2"><div class="field"><label>员工账号</label><input id="s_user" value="'+esc(u.username||'')+'"></div><div class="field"><label>显示名称</label><input id="s_display" value="'+esc(u.display_name||'')+'"></div><div class="field"><label>密码 '+(u.id?'（留空不改）':'')+'</label><input id="s_pw" type="password" value=""></div><div class="field"><label>状态</label><select id="s_active"><option value="1" '+(u.active!==0?'selected':'')+'>启用</option><option value="0" '+(u.active===0?'selected':'')+'>停用</option></select></div></div><div class="field"><label>权限点</label><div class="perm-grid">'+perms.map(x=>{let g='其他';const k=x[0];if(/dashboard|manual|order|sales_stats|record/.test(k))g='经营与销售';else if(/finance|bill|fund|receivable|payable|ledger|due|payment/.test(k))g='财务与往来';else if(/product|customer|company/.test(k))g='客户与商品';else if(/purchase|supplier|inventory|loan/.test(k))g='采购与库存';else if(/print|security|audit|system|backup|staff/.test(k))g='系统';x._g=g;return x}).sort((a,b)=>String(a._g||'').localeCompare(String(b._g||''),'zh')).map((x,i,a)=>(i===0||a[i-1]._g!==x._g?'<div class="qdt-perm-group"><b>'+esc(x._g)+'</b><div class="perm-grid">':'')+'<label><input type="checkbox" data-perm="'+x[0]+'" style="width:auto" '+(selected.includes(x[0])?'checked':'')+'> '+esc(x[1])+'</label>'+(i===a.length-1||a[i+1]._g!==x._g?'</div></div>':'')).join('')+'</div></div>',async()=>{const body={username:$('#s_user').value,display_name:$('#s_display').value,password:$('#s_pw').value,active:Number($('#s_active').value),permissions:$$('[data-perm]:checked').map(x=>x.dataset.perm)};if(!u.id&&!body.password)body.password='Staff@8282';await api(u.id?'/api/admin/staff/'+u.id:'/api/admin/staff',{method:u.id?'PUT':'POST',body:JSON.stringify(body)});toast('员工权限已保存','ok');await refresh()})}
let manualItems=[{product_id:0,qty:1}];
async function pageManual(){const j=await api('/api/admin/manual/data');if(!manualItems.length||!manualItems[0].product_id)manualItems=[{product_id:j.products[0]?.id||0,qty:1}];const customerOpts='<option value="0">散客 / 零售客户</option>'+j.customers.map(c=>'<option value="'+c.id+'">'+esc(c.company||c.display_name||c.username)+'（'+esc(c.username)+'）</option>').join('');const productOpts=j.products.map(p=>'<option value="'+p.id+'">'+esc(p.name)+' · '+money(p.price_cents)+'</option>').join('');$('#page').innerHTML='<div class="grid manual-grid"><div class="card"><h2>管理员 / 员工手动开单</h2><p class="hint">适合门店零售、朋友拿货、电话下单。散客默认必须现结，不产生记账欠款；也可选择已有客户并记账。</p><div class="grid g2"><div class="field"><label>选择客户</label><select id="m_customer">'+customerOpts+'</select></div><div class="field"><label>客户等级</label><select id="m_level">'+['零售','渠道','核心'].map(x=>'<option>'+x+'</option>').join('')+'</select></div><div class="field"><label>客户 / 公司</label><input id="m_name" placeholder="散客可不填，自动记为散客"></div><div class="field"><label>电话</label><input id="m_phone"></div><div class="field"><label>付款方式</label><select id="m_pay">'+['现金','微信','支付宝','银行转账','记账'].map(x=>'<option>'+x+'</option>').join('')+'</select></div><div class="field"><label>备注</label><input id="m_note"></div></div><div class="field"><label>快速批量添加商品</label><input id="m_search" placeholder="搜索商品名称 / SKU / 型号"><div id="m_picker" class="manual-picker"></div><button class="btn ghost sm" id="m_batch">＋ 批量加入勾选商品</button></div><div class="field"><label>商品明细</label><div id="m_items"></div><button class="btn ghost sm" id="m_add">＋ 增加一行</button></div><button class="btn" id="m_submit" style="width:100%;margin-top:12px">保存并打印订单</button></div><div class="card"><h2>价格预览</h2><div id="m_preview"></div></div></div>';function drawPicker(){const q=String($('#m_search')?.value||'').toLowerCase();$('#m_picker').innerHTML=j.products.filter(p=>!q||String((p.name||'')+(p.sku||'')+(p.model||'')).toLowerCase().includes(q)).map(p=>'<label class="pick-item"><input type="checkbox" data-mp="'+p.id+'" style="width:auto"> '+esc(p.name)+' · '+esc(p.sku||'')+' · '+money(p.price_cents)+'</label>').join('')||'<div class="empty">没有匹配商品</div>'}function drawItems(){$('#m_items').innerHTML=manualItems.map((it,i)=>'<div class="grid g3" style="align-items:end;margin-bottom:8px"><div class="field" style="margin:0"><label>商品</label><select data-mi="'+i+'">'+j.products.map(p=>'<option value="'+p.id+'" '+(Number(it.product_id)===Number(p.id)?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></div><div class="field" style="margin:0"><label>购买数量</label><input type="number" min="1" value="'+it.qty+'" data-mq="'+i+'"></div><button class="btn ghost sm" data-md="'+i+'">删除</button></div>').join('');$$('[data-mi]').forEach(x=>x.onchange=()=>{manualItems[Number(x.dataset.mi)].product_id=Number(x.value);calcPreview()});$$('[data-mq]').forEach(x=>x.oninput=()=>{manualItems[Number(x.dataset.mq)].qty=Number(x.value||1);calcPreview()});$$('[data-md]').forEach(x=>x.onclick=()=>{manualItems.splice(Number(x.dataset.md),1);if(!manualItems.length)manualItems=[{product_id:j.products[0]?.id||0,qty:1}];drawItems();calcPreview()})}function calcPreview(){const level=$('#m_level').value;let total=0,html='';for(const it of manualItems){const p=j.products.find(x=>Number(x.id)===Number(it.product_id));if(!p)continue;const c=calcLocal(p,level,it.qty);total+=c.line_total_cents;html+='<div class="preview-line"><b>'+esc(p.name)+'</b><div>单价 '+money(c.unit_price_cents)+' × 计价 '+c.charge_qty+' = '+money(c.line_total_cents)+'</div><div class="hint">实发 '+c.final_qty+(c.gift_qty?'（含赠 '+c.gift_qty+'）':'')+'</div>'+(c.rule_note?'<div class="rule-note">'+esc(c.rule_note)+'</div>':'')+'</div>'}$('#m_preview').innerHTML='<div class="big-money">'+money(total)+'</div>'+html+'<p class="hint">提交后自动生成订单、扣库存、生成打印任务；如选择已有客户 + 记账，会生成账单。</p>'}drawPicker();drawItems();calcPreview();$('#m_search').oninput=drawPicker;$('#m_batch').onclick=()=>{$$('[data-mp]:checked').forEach(x=>manualItems.push({product_id:Number(x.dataset.mp),qty:1}));$$('[data-mp]').forEach(x=>x.checked=false);drawItems();calcPreview();toast('已批量加入商品','ok')};$('#m_add').onclick=()=>{manualItems.push({product_id:j.products[0]?.id||0,qty:1});drawItems();calcPreview()};$('#m_level').onchange=calcPreview;$('#m_customer').onchange=()=>{const c=j.customers.find(x=>String(x.id)===$('#m_customer').value);if(c){$('#m_name').value=c.company||c.display_name||'';$('#m_level').value=c.level||'零售';$('#m_pay').value='记账';calcPreview()}else{$('#m_name').value='散客';$('#m_level').value='零售';$('#m_pay').value='现金';calcPreview()}};$('#m_submit').onclick=async()=>{const items=manualItems.map(x=>({product_id:Number(x.product_id),qty:Number(x.qty||1)}));if(!items.length||items.some(x=>!x.product_id||x.qty<1))return toast('请检查商品数量','err');const body={customer_id:Number($('#m_customer').value),customer_name:$('#m_name').value,company:$('#m_name').value,phone:$('#m_phone').value,level:$('#m_level').value,pay_method:$('#m_pay').value,note:$('#m_note').value,items};const r=await api('/api/admin/manual/order',{method:'POST',body:JSON.stringify(body)});toast('手动开单成功 '+r.order_no,'ok');if(r.auto_notes&&r.auto_notes.length)toast('已自动应用规则：'+r.auto_notes.join('；'),'ok');await loadMe();navigate('orders')}}
async function pageAdminRecords(){const j=await api('/api/admin/records');$('#page').innerHTML='<div class="card"><div class="toolbar"><h2>记录查询</h2><input id="r_q" placeholder="单号 / 客户 / 公司 / 备注" style="max-width:260px"><select id="r_user" style="max-width:220px"><option value="">全部客户</option>'+j.users.map(u=>'<option value="'+u.id+'">'+esc(u.company||u.display_name||u.username)+'</option>').join('')+'</select><input type="date" id="r_from" style="max-width:160px"><input type="date" id="r_to" style="max-width:160px"><button class="btn" id="r_search">查询</button></div><div id="r_result"></div></div>';function renderRecords(d){$('#r_result').innerHTML='<div class="grid g2"><div class="card"><h3>订单记录</h3>'+tbl(['单号','客户','来源','总额','状态','出单','操作'],d.orders.map(o=>[esc(o.order_no),esc(o.customer_snapshot||o.company||o.display_name),esc(o.source||'客户下单'),money(o.total_cents),statusBadge(o.status),printBadge(o.print_status),'<button class="btn ghost sm" data-print-order="'+o.id+'" data-scope="admin">打印明细</button>']))+'</div><div class="card"><h3>退换货记录</h3>'+tbl(['单号','客户','类型','金额','状态','时间'],d.returns.map(r=>[esc(r.return_no),esc(r.company||r.display_name),esc(r.kind),money(r.total_cents),esc(r.status),fmt(r.created_at)]))+'</div></div><div class="grid g2" style="margin-top:14px"><div class="card"><h3>账单记录</h3>'+tbl(['账单','客户','来源','总额','未结','状态','时间'],d.bills.map(b=>[esc(b.bill_no),esc(b.company||b.display_name),esc(b.source_type),money(b.total_cents),money(b.balance_cents),esc(b.status),fmt(b.created_at)]))+'</div><div class="card"><h3>收款 / 付款记录</h3>'+tbl(['客户','类型','金额','方式','备注','时间'],d.payments.map(p=>[esc(p.company||p.display_name),esc(p.bill_kind),money(p.amount_cents),esc(p.pay_method),esc(p.note||''),fmt(p.created_at)]))+'</div></div>';drawAllTables()}renderRecords(j);$('#r_search').onclick=async()=>{const q=new URLSearchParams({q:$('#r_q').value,user_id:$('#r_user').value,from:$('#r_from').value,to:$('#r_to').value});renderRecords(await api('/api/admin/records?'+q.toString()))}}
async function pageAdminPrints(){const j=await api('/api/admin/print/jobs');$('#page').innerHTML='<div class="grid g2"><div class="card"><h2>打印队列</h2><p class="hint">公司电脑运行打印代理后，新订单会自动调用本机 lp/lpr 打印；前台和后台状态会实时同步。</p>'+tbl(['任务','订单','状态','打印机','时间','操作'],j.rows.map(x=>[x.id,esc(x.order_no),'<span class="badge '+(x.status==='已打印'?'ok':x.status==='失败'?'err':'warn')+'">'+esc(printLabel(x.status))+'</span>',esc(x.printer||'默认'),fmt(x.created_at),x.status==='待打印'&&can('print:manage')?'<button class="btn ok sm" data-pok="'+x.id+'">标记'+esc(A.site.print_done_label||'已出单')+'</button> <button class="btn ghost sm" data-psee="'+x.id+'">内容</button>':'<button class="btn ghost sm" data-psee="'+x.id+'">内容</button>']))+'</div><div class="card"><h2>本地打印代理</h2><p>在装有打印机的公司电脑上运行：</p><pre style="white-space:pre-wrap;background:#0f172a;color:#a7f3d0;padding:14px;border-radius:12px;overflow:auto">QDT_URL=http://服务器IP:8282\nQDT_COOKIE=管理员或员工登录Cookie\nnode print-agent.mjs\n</pre><p class="hint">代理每 3 秒拉取待打印任务；调用 lp/lpr 后回写「已打印」。首次使用请先配置 CUPS 打印机。</p></div></div>';$$('[data-pok]').forEach(b=>b.onclick=async()=>{await api('/api/admin/print/jobs/'+b.dataset.pok+'/status',{method:'POST',body:JSON.stringify({status:'已打印'})});toast('已标记','ok');await pageAdminPrints()});$$('[data-psee]').forEach(b=>b.onclick=()=>{const x=j.rows.find(y=>String(y.id)===b.dataset.psee);modal('打印内容 '+x.order_no,'<pre style="white-space:pre-wrap">'+esc(x.payload)+'</pre>')})}
async function pageAdminNotices(){const j=await api('/api/admin/notices');$('#page').innerHTML='<div class="card"><div class="toolbar"><h2>滚动通知 / 弹窗</h2><span class="spacer"></span><button class="btn" id="notice_new">＋ 新增通知</button></div>'+tbl(['类型','标题','内容','启用','操作'],j.rows.map(x=>[esc(x.type),esc(x.title),esc(x.content),x.active?'是':'否','<button class="btn ghost sm" data-ne="'+x.id+'">编辑</button>']))+'</div>';drawAllTables();Object.values(TBL).forEach(s=>s.bind=()=>bind());const bind=()=>$$('[data-ne]').forEach(b=>b.onclick=()=>{const x=j.rows.find(y=>String(y.id)===b.dataset.ne);if(!x)return toast('通知不存在','err');modal('编辑通知','<div class="field"><label>类型</label><select id="n_type"><option value="scroll" '+(x.type==='scroll'?'selected':'')+'>滚动通知</option><option value="popup" '+(x.type==='popup'?'selected':'')+'>弹窗公告</option></select></div><div class="field"><label>标题</label><input id="n_title" value="'+esc(x.title)+'"></div><div class="field"><label>内容</label><textarea id="n_content" rows="4">'+esc(x.content)+'</textarea></div><div class="field"><label>启用</label><select id="n_active"><option value="1" '+(x.active?'selected':'')+'>是</option><option value="0" '+(!x.active?'selected':'')+'>否</option></select></div>',async()=>{await api('/api/admin/notices/'+x.id,{method:'PUT',body:JSON.stringify({type:$('#n_type').value,title:$('#n_title').value,content:$('#n_content').value,active:Number($('#n_active').value)})});toast('已保存，前台实时同步','ok');await pageAdminNotices()})});bind();$('#notice_new').onclick=()=>modal('新增通知','<div class="field"><label>类型</label><select id="n_type"><option value="scroll">滚动通知</option><option value="popup">弹窗公告</option></select></div><div class="field"><label>标题</label><input id="n_title"></div><div class="field"><label>内容</label><textarea id="n_content" rows="4"></textarea></div>',async()=>{await api('/api/admin/notices',{method:'POST',body:JSON.stringify({type:$('#n_type').value,title:$('#n_title').value,content:$('#n_content').value,active:1})});toast('已新增','ok');await pageAdminNotices()})}
async function renderSettingsBox(){const j=await api('/api/admin/settings'),s=j.settings;const f=(k,label,type='text')=>'<div class="field"><label>'+label+'</label><input type="'+type+'" id="set_'+k+'" value="'+esc(s[k]||'')+'"></div>';const ta=(k,label,rows=3)=>'<div class="field"><label>'+label+'</label><textarea id="set_'+k+'" rows="'+rows+'">'+esc(s[k]||'')+'</textarea></div>';$('#settings_box').innerHTML='<h3>连续纸送货单</h3><p class="hint">适配 241 连续针式纸；overlay 只叠加文字到预印刷单据，full 绘制完整表格线。</p>'+f('print_title','送货单标题')+f('print_company_address','公司地址')+f('print_company_phone','公司电话')+f('print_bank_account','收款账户')+f('print_footer','底部说明')+f('print_paper_width_mm','纸张宽 mm','number')+f('print_paper_height_mm','纸张高 mm','number')+'<div class="field"><label>打印模式</label><select id="set_print_form_mode"><option value="overlay" '+(String(s.print_form_mode||'overlay')==='overlay'?'selected':'')+'>叠加预印刷表格（推荐）</option><option value="full" '+(String(s.print_form_mode||'')==='full'?'selected':'')+'>完整绘制表格</option></select></div><h3>全体公告 / LED</h3><div class="field"><label>启用全体公告弹窗</label><select id="set_popup_enabled"><option value="1" '+(String(s.popup_enabled||'1')==='1'?'selected':'')+'>启用</option><option value="0">停用</option></select></div>'+f('popup_title','公告弹窗标题')+ta('popup_content','公告弹窗内容')+f('popup_image','公告图片链接')+f('scroll_text','全站 LED 滚动文字')+f('scroll_speed','滚动秒数','number')+'<h3>账期到期弹窗</h3><div class="field"><label>启用账期弹窗</label><select id="set_due_popup_enabled"><option value="1" '+(String(s.due_popup_enabled||'1')==='1'?'selected':'')+'>启用</option><option value="0">停用</option></select></div>'+f('due_popup_title','账期弹窗标题')+ta('due_popup_template','账期弹窗文字模板',4)+'<p class="hint">自动变量：{company} {username} {bill_count} {amount} {due_date} {days} {payment_days} {overdue}；金额和日期自动填入。</p>'+f('due_popup_days','提前提醒天数','number')+f('due_popup_repeat','每次刷新重复提醒（1/0）','number')+'<h3>公司 / 收款资料</h3>'+f('company_profile_name','公司抬头')+f('company_profile_contact','联系人')+f('company_profile_phone','电话')+f('company_profile_address','地址')+f('company_profile_tax_no','税号')+ta('company_profile_note','付款提示',2)+'<h3>其他</h3>'+f('overdue_days','全站默认账期天数','number')+f('site_name','站点名称')+f('site_subtitle','副标题')+f('printer_name','打印机名称')+f('print_done_label','前台「已打印」显示文案')+f('print_pending_label','前台「待打印」显示文案')+f('print_none_label','前台「无需打印」显示文案')+f('print_fail_label','前台「打印失败」显示文案')+f('order_success_label','订单成功状态文案')+f('table_page_size','表格每页条数','number')+f('live_poll_seconds','实时轮询秒数','number')+'<button class="btn" id="set_save">保存设置</button>';$('#set_save').onclick=async()=>{const keys=['print_title','print_company_address','print_company_phone','print_bank_account','print_footer','print_paper_width_mm','print_paper_height_mm','popup_title','popup_image','scroll_text','scroll_speed','due_popup_title','due_popup_days','due_popup_repeat','company_profile_name','company_profile_contact','company_profile_phone','company_profile_address','company_profile_tax_no','overdue_days','site_name','site_subtitle','printer_name','print_done_label','print_pending_label','print_none_label','print_fail_label','order_success_label','table_page_size','live_poll_seconds'];const body={popup_enabled:$('#set_popup_enabled').value,auto_print:'1',due_popup_enabled:$('#set_due_popup_enabled').value,print_form_mode:$('#set_print_form_mode').value};keys.forEach(k=>body[k]=$('#set_'+k).value);body.popup_content=$('#set_popup_content').value;body.due_popup_template=$('#set_due_popup_template').value;body.company_profile_note=$('#set_company_profile_note').value;await api('/api/admin/settings',{method:'POST',body:JSON.stringify(body)});toast('设置已保存，前台会实时同步','ok');await loadMe();renderShell();navigate(A.route);startLive()}}
async function pageAdminSettings(){const j=await api('/api/admin/settings'),s=j.settings;$('#page').innerHTML='<div class="card"><h2>系统设置</h2><div id="settings_box"></div></div>';await renderSettingsBox()}
async function pageAdminBackup(){$('#page').innerHTML='<div class="grid g2"><div class="card"><h2>整机备份</h2><p class="hint">导出全部客户、商品、订单、账单、通知、打印任务、员工权限、规则、设置与审计日志。</p><a class="btn" href="/api/admin/backup" download="qudingtong-backup.json">下载备份</a> <button class="btn ghost" id="bk_save">保存到服务器</button></div><div class="card"><h2>恢复备份</h2><div class="field"><label>选择 JSON 备份文件</label><input type="file" id="bk_file" accept="application/json,.json"></div><button class="btn warn" id="bk_restore">恢复备份</button><p class="hint">恢复会覆盖当前数据，建议先下载备份。</p></div></div>';$('#bk_save').onclick=async()=>{const j=await api('/api/admin/backup/save',{method:'POST',body:'{}'});toast('已保存 '+j.file,'ok')};$('#bk_restore').onclick=async()=>{const f=$('#bk_file').files[0];if(!f)return toast('请选择备份文件','err');const backup=JSON.parse(await f.text());await api('/api/admin/backup/restore',{method:'POST',body:JSON.stringify({backup})});toast('已恢复','ok');setTimeout(()=>location.reload(),700)}}
