async function pagePayInfo(){const j=await api('/api/company-profile'),s=j.site||{},accounts=j.accounts||[],qrs=j.qrcodes||[];$('#page').innerHTML='<div class="grid g2"><div class="card"><h2>公司信息</h2><p><b>'+esc(s.company_profile_name||'')+'</b></p><p class="hint">联系人：'+esc(s.company_profile_contact||'—')+'　电话：'+esc(s.company_profile_phone||'—')+'</p><p class="hint">地址：'+esc(s.company_profile_address||'—')+'</p><p class="hint">税号：'+esc(s.company_profile_tax_no||'—')+'</p><p class="hint">'+esc(s.company_profile_note||'')+'</p></div><div class="card"><h2>收款账号</h2>'+(accounts.length?accounts.map(x=>'<div class="preview-line"><b>'+esc(x.name)+'（'+esc(x.account_type||'对公')+'）</b><br>账号：'+esc(x.account_no)+'<br>开户行：'+esc(x.bank_name||'—')+(x.branch?' / '+esc(x.branch):'')+(x.swift?'<br>SWIFT：'+esc(x.swift):'')+(x.note?'<br><span class="hint">'+esc(x.note)+'</span>':'')+'</div>').join(''):'<div class="empty">暂未设置收款账户</div>')+'</div></div><div class="card" style="margin-top:14px"><h2>收款二维码</h2><div class="qr-grid">'+(qrs.length?qrs.map(x=>'<div class="qr-item"><img src="'+esc(x.image)+'" alt="'+esc(x.title)+'"><b>'+esc(x.title)+'</b>'+(x.note?'<span class="hint">'+esc(x.note)+'</span>':'')+'</div>').join(''):'<div class="empty">暂未上传二维码</div>')+'</div></div>';drawAllTables()}
async function pageAdminPayments(){const [a,q]=await Promise.all([api('/api/admin/payment-accounts'),api('/api/admin/payment-qrcodes')]);$('#page').innerHTML='<div class="grid g2"><div class="card"><div class="toolbar"><h2>公司信息 / 收款账号</h2><span class="spacer"></span><button class="btn" id="pa_new">＋ 新增账户</button></div>'+tbl(['名称','账号','开户行','类型','状态','操作'],(a.rows||[]).map(x=>[esc(x.name),esc(x.account_no),esc(x.bank_name||'—'),esc(x.account_type||''),x.active?'启用':'停用','<button class="btn ghost sm" data-pae="'+x.id+'">编辑</button> <button class="btn warn sm" data-pad="'+x.id+'">删除</button>']))+'</div><div class="card"><div class="toolbar"><h2>收款二维码</h2><span class="spacer"></span><button class="btn" id="pq_new">＋ 上传二维码</button></div><div class="qr-grid">'+(q.rows||[]).map(x=>'<div class="qr-item"><img src="'+esc(x.image)+'" alt="'+esc(x.title)+'"><b>'+esc(x.title)+'</b><span class="hint">'+esc(x.note||'')+'</span><button class="btn warn sm" data-pqd="'+x.id+'">删除</button></div>').join('')+'</div></div></div><p class="hint" style="margin-top:12px">公司抬头、联系人、电话、地址、税号和付款提示在「系统设置」中配置；保存后所有前台实时同步。</p>';$('#pa_new').onclick=()=>paymentAccountModal({},pageAdminPayments);$$('[data-pae]').forEach(b=>b.onclick=()=>paymentAccountModal((a.rows||[]).find(x=>String(x.id)===b.dataset.pae),pageAdminPayments));$$('[data-pad]').forEach(b=>b.onclick=async()=>{if(!confirm('确认删除该收款账户？'))return;await api('/api/admin/payment-accounts/'+b.dataset.pad,{method:'DELETE',body:'{}'});toast('已删除','ok');await pageAdminPayments()});$('#pq_new').onclick=()=>qrcodeModal(pageAdminPayments);$$('[data-pqd]').forEach(b=>b.onclick=async()=>{if(!confirm('确认删除该二维码？'))return;await api('/api/admin/payment-qrcodes/'+b.dataset.pqd,{method:'DELETE',body:'{}'});toast('已删除','ok');await pageAdminPayments()});drawAllTables()}
function paymentAccountModal(x,refresh){x=x||{};modal(x.id?'编辑收款账户':'新增收款账户','<div class="grid g2"><div class="field"><label>名称</label><input id="pa_name" value="'+esc(x.name||'')+'"></div><div class="field"><label>账号</label><input id="pa_no" value="'+esc(x.account_no||'')+'"></div><div class="field"><label>开户行</label><input id="pa_bank" value="'+esc(x.bank_name||'')+'"></div><div class="field"><label>账户类型</label><select id="pa_type">'+['对公','银行卡','微信','支付宝','其他'].map(v=>'<option '+(x.account_type===v?'selected':'')+'>'+v+'</option>').join('')+'</select></div><div class="field"><label>支行 / 开户网点</label><input id="pa_branch" value="'+esc(x.branch||'')+'"></div><div class="field"><label>SWIFT / 行号</label><input id="pa_swift" value="'+esc(x.swift||'')+'"></div></div><div class="field"><label>备注</label><input id="pa_note" value="'+esc(x.note||'')+'"></div><label class="hint"><input type="checkbox" id="pa_active" style="width:auto" '+(x.id&&!x.active?'':'checked')+'> 启用</label>',async()=>{const body={name:$('#pa_name').value,account_no:$('#pa_no').value,bank_name:$('#pa_bank').value,account_type:$('#pa_type').value,branch:$('#pa_branch').value,swift:$('#pa_swift').value,note:$('#pa_note').value,active:$('#pa_active').checked?1:0,sort:Number(x.sort||0)};await api(x.id?'/api/admin/payment-accounts/'+x.id:'/api/admin/payment-accounts',{method:x.id?'PUT':'POST',body:JSON.stringify(body)});toast('收款账户已保存','ok');await refresh()})}
function qrcodeModal(refresh){modal('上传收款二维码','<div class="field"><label>标题（如：微信 / 支付宝 / 对公）</label><input id="pq_title"></div><div class="field"><label>图片文件（PNG/JPG/WEBP/GIF）</label><input id="pq_file" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></div><div class="field"><label>备注</label><input id="pq_note"></div><p class="hint">图片会转为安全 Data URL 存入数据库，并随整机备份一起保存；前台实时同步。</p>',async()=>{const f=$('#pq_file').files[0];if(!f)throw new Error('请选择二维码图片');if(f.size>5*1024*1024)throw new Error('图片不能超过 5MB');const image=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result));r.onerror=no;r.readAsDataURL(f)});const body={title:$('#pq_title').value||'收款二维码',image,note:$('#pq_note').value,active:1,sort:0};await api('/api/admin/payment-qrcodes',{method:'POST',body:JSON.stringify(body)});toast('二维码已上传','ok');await refresh()})}
async function pageAdminDue(){const j=await api('/api/admin/due-reminders');$('#page').innerHTML='<div class="grid g4"><div class="stat"><div class="k">即将到期客户</div><div class="v">'+(j.rows||[]).length+'</div></div><div class="stat"><div class="k">合计未结金额</div><div class="v money">'+money(j.total_amount_cents||0)+'</div></div><div class="stat"><div class="k">提前提醒</div><div class="v">'+j.remind_days+' 天</div></div><div class="stat"><div class="k">动态计算</div><div class="v">实时</div></div></div><div class="card" style="margin-top:14px"><h2>账期即将到期客户 / 弹窗预览</h2>'+tbl(['客户','账号','账期','账单数','未结金额','最近到期','剩余/逾期','弹窗文字'],(j.rows||[]).map(x=>[esc(x.company||x.display_name||'—'),esc(x.username),x.payment_days+' 天',x.bill_count,esc(x.amount),esc(x.due_date||'—'),x.overdue?'<span class="badge err">已逾期</span>':x.days+' 天','<button class="btn ghost sm" data-dueview="'+x.user_id+'">查看弹窗</button>']))+'</div>';$$('[data-dueview]').forEach(b=>b.onclick=()=>{const x=(j.rows||[]).find(r=>String(r.user_id)===b.dataset.dueview);popupHtml('账期弹窗预览 · '+esc(x.username),'<div style="font-size:15px;line-height:1.9;white-space:pre-wrap">'+esc(x.message||'')+'</div>','due-preview')});drawAllTables()}
async function pageAdminFinanceCenter(){const j=await api('/api/admin/finance/overview');$('#page').innerHTML='<div class="grid g4"><div class="stat"><div class="k">客户应收</div><div class="v money">'+money(j.total_receivable_cents)+'</div></div><div class="stat"><div class="k">供货商应付</div><div class="v money">'+money(j.total_payable_cents)+'</div></div><div class="stat"><div class="k">客户</div><div class="v">'+j.customers.length+'</div></div><div class="stat"><div class="k">供货商</div><div class="v">'+j.suppliers.length+'</div></div></div><div class="grid g2" style="margin-top:14px"><div class="card"><h2>客户应收</h2>'+tbl(['客户','账号','电话','未结','销售单','退货单','操作'],j.customers.map(u=>[esc(u.company||u.display_name),esc(u.username),esc(u.phone||'—'),money(u.balance_cents),u.order_count,u.return_count,'<button class="btn ghost sm" data-fc="'+u.id+'">明细</button>']))+'</div><div class="card"><h2>供货商应付</h2>'+tbl(['供货商','编码','电话','未结','进货单','操作'],j.suppliers.map(s=>[esc(s.name||s.short_name),esc(s.code||'—'),esc(s.phone||'—'),money(s.balance_cents),s.purchase_count,'<button class="btn ghost sm" data-fs="'+s.id+'">明细</button>']))+'</div></div>';drawAllTables();const detail=async(path,title)=>{const d=await api(path);let h='<h2>'+esc(title)+'</h2>';if(d.user){h+='<div class="grid g3"><div class="stat"><div class="k">应收未结</div><div class="v money">'+money(d.total_receivable_cents)+'</div></div><div class="stat"><div class="k">销售订单</div><div class="v">'+d.orders.length+'</div></div><div class="stat"><div class="k">退货单</div><div class="v">'+d.returns.length+'</div></div></div><div class="card" style="margin-top:12px"><h3>销售订单</h3>'+tbl(['单号','时间','金额','状态','出单','操作'],d.orders.map(o=>[esc(o.order_no),fmt(o.created_at),money(o.total_cents),statusBadge(o.status),printBadge(o.print_status),'<button class="btn ghost sm" data-print-order="'+o.id+'" data-scope="admin">打印</button>']))+'</div><div class="card" style="margin-top:12px"><h3>退货单</h3>'+tbl(['单号','时间','金额','状态','类型'],d.returns.map(o=>[esc(o.return_no),fmt(o.created_at),money(o.total_cents),esc(o.status),esc(o.kind)]))+'</div><div class="grid g2" style="margin-top:12px"><div class="card"><h3>账单</h3>'+tbl(['账单','来源','总额','未结','状态','到期'],d.bills.map(x=>[esc(x.bill_no),esc(x.source_type),money(x.total_cents),money(x.balance_cents),esc(x.status),esc(x.due_at)]))+'</div><div class="card"><h3>收款 / 冲抵</h3>'+tbl(['类型','金额','方式','备注','时间'],d.payments.map(x=>[esc(x.bill_kind),money(x.amount_cents),esc(x.pay_method),esc(x.note||''),fmt(x.created_at)]))+'</div></div>'}else{h+='<div class="grid g3"><div class="stat"><div class="k">应付未结</div><div class="v money">'+money(d.total_payable_cents)+'</div></div><div class="stat"><div class="k">进货单</div><div class="v">'+(d.purchase_orders||[]).length+'</div></div><div class="stat"><div class="k">付款记录</div><div class="v">'+d.supplier_payments.length+'</div></div></div><div class="card" style="margin-top:12px"><h3>进货 / 采购单</h3>'+tbl(['单号','时间','金额','状态'],(d.purchase_orders||[]).map(x=>[esc(x.po_no),fmt(x.occurred_at),money(x.total_cents),esc(x.status)]))+'</div><div class="grid g2" style="margin-top:12px"><div class="card"><h3>应付账单</h3>'+tbl(['账单','总额','未结','状态','到期'],d.supplier_bills.map(x=>[esc(x.bill_no),money(x.total_cents),money(x.balance_cents),esc(x.status),esc(x.due_at)]))+'</div><div class="card"><h3>付款</h3>'+tbl(['金额','方式','备注','时间'],d.supplier_payments.map(x=>[money(x.amount_cents),esc(x.pay_method),esc(x.note||''),fmt(x.occurred_at)]))+'</div></div>'}popupHtml(title,h,'pay-pop');drawAllTables()};$$('[data-fc]').forEach(x=>x.onclick=async()=>{const u=j.customers.find(y=>String(y.id)===x.dataset.fc);await detail('/api/admin/finance/customer/'+x.dataset.fc,'客户明细 · '+(u.company||u.display_name||u.username))});$$('[data-fs]').forEach(x=>x.onclick=async()=>{const s=j.suppliers.find(y=>String(y.id)===x.dataset.fs);await detail('/api/admin/finance/supplier/'+x.dataset.fs,'供货商明细 · '+(s.name||s.short_name))})}
async function pageAdminInventoryAdjust(){const j=await api('/api/admin/inventory/adjustments');$('#page').innerHTML='<div class="grid g2"><div class="card"><h2>报损 / 报溢</h2><p class="hint">报损减少库存，报溢增加库存；只影响库存与库存流水，不修改历史订单金额。</p><div class="field"><label>类型</label><select id="adj_kind"><option>报损</option><option>报溢</option></select></div><div class="field"><label>商品</label><select id="adj_product">'+j.products.map(p=>'<option value="'+p.id+'">'+esc(p.name)+' · '+esc(p.sku||'')+' · 库存 '+p.stock+'</option>').join('')+'</select></div><div class="field"><label>数量</label><input id="adj_qty" type="number" min="1" value="1"></div><div class="field"><label>原因</label><input id="adj_reason"></div><button class="btn" id="adj_save">保存调整</button></div><div class="card"><h2>调整记录</h2>'+tbl(['时间','商品','类型','数量','前库存','后库存','金额','原因','操作人'],j.rows.map(r=>[fmt(r.occurred_at),esc(r.product_name),esc(r.kind),r.qty,r.stock_before,r.stock_after,money(r.amount_cents),esc(r.reason||''),esc(r.operator_name||'')]))+'</div></div>';drawAllTables();$('#adj_save').onclick=async()=>{try{await api('/api/admin/inventory/adjustments',{method:'POST',body:JSON.stringify({kind:$('#adj_kind').value,product_id:Number($('#adj_product').value),qty:Number($('#adj_qty').value),reason:$('#adj_reason').value})});toast('库存已调整','ok');await pageAdminInventoryAdjust()}catch(e){toast(e.message,'err')}}}
async function pageAdminInventoryCheck(){const q=new URLSearchParams({category:A.invCat||'',q:A.invQ||'',sort:A.invSort||'category'}),j=await api('/api/admin/inventory/check?'+q);$('#page').innerHTML='<div class="card"><div class="toolbar"><h2>库存盘点</h2><input id="inv_q" placeholder="搜索名称 / SKU / 型号" value="'+esc(A.invQ||'')+'" style="max-width:260px"><select id="inv_cat" style="max-width:180px"><option value="">全部分类</option>'+j.categories.map(c=>'<option '+(A.invCat===c?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select><select id="inv_sort"><option value="category">按类目</option><option value="stock">按数量</option><option value="name">按名称</option><option value="amount">按库存金额</option></select><button class="btn ghost" id="inv_refresh">刷新</button><span class="spacer"></span><button class="btn" id="inv_print">打印 A4 盘点表</button></div><p class="hint">共 '+j.total_sku+' 个 SKU，账面数量 '+j.total_qty+'，库存成本 '+money(j.total_cost_cents)+'；默认隐藏 0 库存商品。</p>'+tbl(['SKU','名称','型号','分类','账面数量','单位','成本单价','库存金额','实盘','备注'],j.rows.map(r=>[esc(r.sku),esc(r.name),esc(r.model||''),esc(r.category||''),r.stock,esc(r.unit||'件'),money(r.cost_cents),money(Number(r.stock)*Number(r.cost_cents)),'', '']))+'</div>';drawAllTables();const reload=async()=>{A.invQ=$('#inv_q').value;A.invCat=$('#inv_cat').value;A.invSort=$('#inv_sort').value;await pageAdminInventoryCheck()};$('#inv_q').onchange=reload;$('#inv_cat').onchange=reload;$('#inv_sort').onchange=reload;$('#inv_refresh').onclick=reload;$('#inv_print').onclick=()=>{const rows=j.rows.map(r=>[esc(r.sku),esc(r.name),esc(r.category||''),r.stock,esc(r.unit||'件'),'','']);printHtml('库存盘点表','<div class="print-form"><h1>库存盘点表</h1><p>打印时间：'+fmt(localDateTime())+'　分类：'+esc(A.invCat||'全部')+'</p><table><thead><tr><th>SKU</th><th>商品名称</th><th>分类</th><th>账面数量</th><th>单位</th><th>实盘数量</th><th>备注</th></tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>')}}
async function pageAdminPrintSettings(){const j=await api('/api/admin/print/settings');const cfg=j.sale||{};$('#page').innerHTML='<div class="card"><h2>打印设置</h2><p class="hint">销售单与退货单共用表格模板；抬头自动替换，销售蓝色、退货红色。保存后所有打印任务和浏览器打印实时生效。</p><div class="grid g2"><div class="field"><label>销售单抬头</label><input id="ps_title" value="'+esc(cfg.title||'')+'"></div><div class="field"><label>退货单抬头</label><input id="ps_return" value="'+esc(cfg.return_title||'')+'"></div><div class="field"><label>纸张</label><select id="ps_size"><option value="A4">A4 盘点 / 明细</option><option value="241">241 连续纸</option></select></div><div class="field"><label>宽度 mm</label><input id="ps_w" type="number" value="'+esc(cfg.paper?.width_mm||240)+'"></div><div class="field"><label>高度 mm</label><input id="ps_h" type="number" value="'+esc(cfg.paper?.height_mm||95.24)+'"></div><div class="field"><label>行高</label><input id="ps_row" type="number" value="'+esc(cfg.rows?.item_height||8)+'"></div></div><h3>列设置</h3>'+tbl(['显示','列名','宽度','对齐','字号','边框','颜色'],(cfg.columns||[]).map((c,i)=>['<input type="checkbox" data-ps-show="'+i+'" style="width:auto" '+(c.show?'checked':'')+'>','<input data-ps-label="'+i+'" value="'+esc(c.label)+'">','<input data-ps-width="'+i+'" value="'+esc(c.width||'')+'">','<select data-ps-align="'+i+'"><option '+(c.align==='left'?'selected':'')+'>left</option><option '+(c.align==='center'?'selected':'')+'>center</option><option '+(c.align==='right'?'selected':'')+'>right</option></select>','<input data-ps-font="'+i+'" type="number" value="'+esc(c.font||11)+'">','<input type="checkbox" data-ps-border="'+i+'" style="width:auto" '+(c.border?'checked':'')+'>','<input data-ps-color="'+i+'" value="'+esc(c.color||'#111')+'">']))+'<button class="btn" id="ps_save">保存打印设置</button></div>';drawAllTables();$('#ps_save').onclick=async()=>{const cols=(cfg.columns||[]).map((c,i)=>({...c,show:$$('[data-ps-show="'+i+'"]')[0]?.checked,label:$$('[data-ps-label="'+i+'"]')[0]?.value||c.label,width:$$('[data-ps-width="'+i+'"]')[0]?.value||c.width,align:$$('[data-ps-align="'+i+'"]')[0]?.value||c.align,font:Number($$('[data-ps-font="'+i+'"]')[0]?.value||11),border:$$('[data-ps-border="'+i+'"]')[0]?.checked,color:$$('[data-ps-color="'+i+'"]')[0]?.value||c.color}));await api('/api/admin/print/settings',{method:'POST',body:JSON.stringify({doc_type:'sale',title:$('#ps_title').value,config:{...cfg,return_title:$('#ps_return').value,columns:cols,rows:{...cfg.rows,item_height:Number($('#ps_row').value||8)},paper:{...cfg.paper,size:$('#ps_size').value,width_mm:Number($('#ps_w').value||240),height_mm:Number($('#ps_h').value||95.24)}}})});toast('打印设置已保存','ok');await pageAdminPrintSettings()}}
window.navigate=navigate;window.renderPage=renderPage;window.printOrder=printOrder;Object.assign(window,{ $, $$, A, APP, api, toast, modal, money, esc, yuan, dt, today, fmt, ck, jparse, parseCsvText, printHtml, tbl, drawAllTables, can, printLabel, statusLabel, statusBadge, printBadge, loadMe, renderShell, productModal, userModal, resetUserModal, staffModal, priceRulesText, giftRulesText, ruleSummaryText, showPaymentInfo, popupHtml, pageAdminPayments, pageAdminDue, pagePayInfo, ADMIN_NAV, ROUTE_PERM, liveRefresh });
